"use client";

import { useEffect } from "react";
import { mountLaserCursor } from "@/lib/oneko/laser-cursor-dom";

export function LaserCursor({ zIndex }: { zIndex: number }) {
  useEffect(() => mountLaserCursor(zIndex), [zIndex]);
  return null;
}

"use client";

/**
 * Installable React component — the classic “cat follows the cursor” idea comes from
 * oneko.js (MIT): https://github.com/adryd325/oneko.js/
 */

import {
  useEffect,
  useImperativeHandle,
  useRef,
  useState,
  useSyncExternalStore,
  type Ref,
} from "react";
import { LaserCursor } from "@/components/laser-cursor";
import { useCatAnimation } from "@/hooks/use-cat-animation";
import { useOnekoPropsSync } from "@/hooks/use-oneko-props-sync";
import { useSkinSource } from "@/hooks/use-skin-source";
import { ONEKO_DEFAULTS } from "@/lib/oneko/defaults";
import { useMotionAllowed, useReducedMotion } from "@/hooks/use-motion-allowed";
import { restingCatStyle } from "@/lib/oneko/resting-cat";
import { laserActive } from "@/lib/oneko/start-cat-animation";
import { createCatControls, type OnekoControls } from "@/lib/oneko/controls";
import { createInitialCatState } from "@/lib/oneko/initial-state";
import { areCatsHidden, onCatsHiddenChange, setCatsHidden } from "@/lib/oneko/pack";
import { readPersistedPosition } from "@/lib/oneko/persistence";
import type { CatActivityState, CatLiveState, OnekoProps } from "@/lib/oneko/types";

export type { CatActivityState, CatLiveState, OnekoControls, OnekoProps };
export type { OnekoSoundEvent, OnekoSounds } from "@/lib/oneko/types";
export type { OnekoSeason } from "@/lib/oneko/seasons";
export type { OnekoSkin } from "@/lib/oneko/skins";
export type { OnekoZone } from "@/lib/oneko/zones";
export { setCatsHidden };

/** The visitor's remembered choice to hide every cat on the site. Pair with setCatsHidden. */
export function useCatsHidden(): boolean {
  return useSyncExternalStore(onCatsHiddenChange, areCatsHidden, () => false);
}

export default function Oneko({
  paused = ONEKO_DEFAULTS.paused,
  followCursor = ONEKO_DEFAULTS.followCursor,
  sleepEnabled = ONEKO_DEFAULTS.sleepEnabled,
  bubblePlacement = ONEKO_DEFAULTS.bubblePlacement,
  bubbleScale = ONEKO_DEFAULTS.bubbleScale,
  soundBasePath = ONEKO_DEFAULTS.soundBasePath,
  sounds,
  storageKey = ONEKO_DEFAULTS.storageKey,
  zones,
  zoneAttractionChance = ONEKO_DEFAULTS.zoneAttractionChance,
  zoneAttractionDuration = ONEKO_DEFAULTS.zoneAttractionDuration,
  skin = ONEKO_DEFAULTS.skin,
  spriteSrc,
  persistPosition = ONEKO_DEFAULTS.persistPosition,
  /** One below max so fixed UI can sit above the cat. */
  zIndex = ONEKO_DEFAULTS.zIndex,
  initialPos,
  speed = ONEKO_DEFAULTS.speed,
  scale = ONEKO_DEFAULTS.scale,
  opacity = ONEKO_DEFAULTS.opacity,
  rotationAmount = ONEKO_DEFAULTS.rotationAmount,
  idleThreshold = ONEKO_DEFAULTS.idleThreshold,
  meow = ONEKO_DEFAULTS.meow,
  onStateChange,
  freerunChance = ONEKO_DEFAULTS.freerunChance,
  freerunDuration = ONEKO_DEFAULTS.freerunDuration,
  bubbleEnabled = ONEKO_DEFAULTS.bubbleEnabled,
  bubbleDisplayFrames = ONEKO_DEFAULTS.bubbleDisplayFrames,
  bubbleCooldown = ONEKO_DEFAULTS.bubbleCooldown,
  hueRotate = ONEKO_DEFAULTS.hueRotate,
  liveStateRef,
  bubbleChance = ONEKO_DEFAULTS.bubbleChance,
  followDistance = ONEKO_DEFAULTS.followDistance,
  animationSpeed = ONEKO_DEFAULTS.animationSpeed,
  bubbleText = ONEKO_DEFAULTS.bubbleText,
  volume = ONEKO_DEFAULTS.volume,
  laserPointer = ONEKO_DEFAULTS.laserPointer,
  reducedMotion = ONEKO_DEFAULTS.reducedMotion,
  chase = ONEKO_DEFAULTS.chase,
  napWhileTyping = ONEKO_DEFAULTS.napWhileTyping,
  followFocus = ONEKO_DEFAULTS.followFocus,
  perchOnHover = ONEKO_DEFAULTS.perchOnHover,
  pettable = ONEKO_DEFAULTS.pettable,
  seasonal = ONEKO_DEFAULTS.seasonal,
  grabbable = ONEKO_DEFAULTS.grabbable,
  treats = ONEKO_DEFAULTS.treats,
  timeOfDay = ONEKO_DEFAULTS.timeOfDay,
  affection = ONEKO_DEFAULTS.affection,
  onPet,
  onCatchCursor,
  onSleep,
  onToss,
  onTreat,
  ref,
}: OnekoProps & {
  /** Imperative controls: goTo, say, sit, follow, pet, and dropTreat. */
  ref?: Ref<OnekoControls>;
}) {
  const hidden = useCatsHidden();
  const motionAllowed = useMotionAllowed() && !hidden;
  const prefersReducedMotion = useReducedMotion();
  const restingSource = useSkinSource(skin, spriteSrc);
  const elRef = useRef<HTMLDivElement | null>(null);
  const lastStateRef = useRef<CatActivityState>("idle");
  const onStateChangeRef = useRef(onStateChange);

  useEffect(() => {
    onStateChangeRef.current = onStateChange;
  }, [onStateChange]);

  const config = {
    paused,
    followCursor,
    sleepEnabled,
    bubblePlacement,
    bubbleScale,
    soundBasePath,
    sounds,
    zones,
    zoneAttractionChance,
    zoneAttractionDuration,
    speed,
    scale,
    opacity,
    rotationAmount,
    idleThreshold,
    freerunChance,
    freerunDuration,
    bubbleEnabled,
    bubbleDisplayFrames,
    bubbleCooldown,
    bubbleChance,
    followDistance,
    animationSpeed,
    bubbleText,
    meow,
    volume,
    laserPointer: laserActive({ laserPointer, followCursor, paused }),
    chase,
    napWhileTyping,
    followFocus,
    perchOnHover,
    seasonal,
    grabbable,
    treats,
    timeOfDay,
    affection,
    onPet,
    onCatchCursor,
    onSleep,
    onToss,
    onTreat,
  };

  const [initialState] = useState(() => createInitialCatState({ initialPos, ...config }));
  const stateRef = useRef(initialState);
  useImperativeHandle(ref, () => createCatControls(stateRef), []);

  useCatAnimation({
    enabled: motionAllowed,
    stateRef,
    elRef,
    lastStateRef,
    onStateChangeRef,
    liveStateRef,
    persistPosition,
    storageKey,
    zIndex,
    pettable,
  });
  useOnekoPropsSync(stateRef, elRef, {
    ...config,
    hueRotate,
    skin,
    spriteSrc,
  });

  if (!hidden && prefersReducedMotion && reducedMotion === "rest" && restingSource) {
    return (
      <RestingCat
        source={restingSource}
        position={(persistPosition && readPersistedPosition(storageKey)) || initialPos}
        scale={scale}
        opacity={opacity}
        hueRotate={hueRotate}
        zIndex={zIndex}
      />
    );
  }

  return motionAllowed && config.laserPointer ? <LaserCursor zIndex={zIndex} /> : null;
}

/** Still, sleeping cat for visitors who prefer reduced motion. */
function RestingCat({
  source,
  position,
  scale,
  opacity,
  hueRotate,
  zIndex,
}: {
  source: string;
  position?: { x: number; y: number };
  scale: number;
  opacity: number;
  hueRotate: number;
  zIndex: number;
}) {
  return (
    <div
      aria-hidden="true"
      style={{
        ...restingCatStyle({ position, scale, zIndex }),
        backgroundImage: `url(${JSON.stringify(source)})`,
        transform: `scale(${scale})`,
        opacity,
        filter: hueRotate ? `hue-rotate(${hueRotate}deg)` : undefined,
      }}
    />
  );
}

"use client";

import { useEffect } from "react";
import { startCatAnimation, type StartCatAnimationOptions } from "@/lib/oneko/start-cat-animation";

export function useCatAnimation({
  enabled,
  stateRef,
  elRef,
  lastStateRef,
  onStateChangeRef,
  liveStateRef,
  persistPosition,
  storageKey,
  zIndex,
  pettable,
}: StartCatAnimationOptions & { enabled: boolean }) {
  useEffect(() => {
    if (!enabled) return;

    return startCatAnimation({
      stateRef,
      elRef,
      lastStateRef,
      onStateChangeRef,
      liveStateRef,
      persistPosition,
      storageKey,
      zIndex,
      pettable,
    });
  }, [
    enabled,
    stateRef,
    elRef,
    lastStateRef,
    onStateChangeRef,
    persistPosition,
    storageKey,
    zIndex,
    pettable,
    liveStateRef,
  ]);
}

"use client";

import { useSyncExternalStore } from "react";

const REDUCED_MOTION_QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const query = window.matchMedia?.(REDUCED_MOTION_QUERY);
  query?.addEventListener("change", onChange);
  return () => query?.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return !(window.matchMedia?.(REDUCED_MOTION_QUERY).matches ?? false);
}

export function useMotionAllowed(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, () => false);
}

/** True only on the client when the visitor asks for reduced motion. */
export function useReducedMotion(): boolean {
  return !useSyncExternalStore(subscribe, getSnapshot, () => true);
}

import { useEffect, useRef } from "react";

/** Soften sprite changes without affecting movement, scale, or the selected tint. */
export function useSpriteAppearance(
  elRef: { current: HTMLElement | null },
  /** Undefined while a skin loads; the current sheet stays until the next one is ready. */
  source: string | undefined,
  hueRotate = 0,
) {
  const previous = useRef<{
    el: HTMLElement;
    source: string;
    filter: string;
  } | null>(null);
  const transition = useRef<Animation | null>(null);

  // Check the element too: the animation engine can remount its DOM independently.
  useEffect(() => {
    const el = elRef.current;
    if (!el || !source) return;
    const filter = hueRotate ? `hue-rotate(${hueRotate}deg)` : "blur(0px)";
    const last = previous.current;
    if (last?.el === el && last.source === source && last.filter === filter) return;

    transition.current?.cancel();
    transition.current = null;
    el.style.backgroundImage = `url(${JSON.stringify(source)})`;
    el.style.filter = filter;
    previous.current = { el, source, filter };

    if (
      last?.el === el &&
      last.source !== source &&
      !window.matchMedia("(prefers-reduced-motion: reduce)").matches &&
      typeof el.animate === "function"
    ) {
      transition.current = el.animate(
        [{ filter: `${filter} blur(2px)` }, { filter: `${filter} blur(0px)` }],
        { duration: 220, easing: "ease-out" },
      );
    }
  });

  useEffect(() => () => transition.current?.cancel(), []);
}

import { useEffect } from "react";
import { useSpriteAppearance } from "@/hooks/use-sprite-appearance";
import { applyRuntimeConfig, type CatRuntimeConfig } from "@/lib/oneko/runtime-config";
import { useSkinSource } from "@/hooks/use-skin-source";
import type { OnekoSkin } from "@/lib/oneko/skins";
import type { CatRuntimeState } from "@/lib/oneko/types";

type SyncableProps = CatRuntimeConfig & {
  hueRotate: number;
  skin: OnekoSkin;
  spriteSrc?: string;
};

export function useOnekoPropsSync(
  stateRef: { current: CatRuntimeState },
  elRef: { current: HTMLDivElement | null },
  props: SyncableProps,
) {
  useSpriteAppearance(elRef, useSkinSource(props.skin, props.spriteSrc), props.hueRotate);

  // Reapply after a render, including when the animation DOM is remounted.
  useEffect(() => {
    const state = stateRef.current;
    applyRuntimeConfig(state, props);
    const el = elRef.current;
    if (!el) return;
    el.style.transform = `scale(${props.scale}) rotate(${state.currentRotation}deg)`;
    el.style.opacity = String(props.opacity);
  });
}

import { useEffect, useState } from "react";
import { getSkinSource, loadSkinSource, type OnekoSkin } from "@/lib/oneko/skins";

/** Sprite sheet to draw: a custom sprite, a ready skin, or undefined while a skin loads. */
export function useSkinSource(skin: OnekoSkin, spriteSrc?: string): string | undefined {
  const ready = spriteSrc || getSkinSource(skin);
  const [, setLoadedSkin] = useState<OnekoSkin>();

  useEffect(() => {
    if (ready) return;
    let current = true;
    loadSkinSource(skin).then(
      () => current && setLoadedSkin(skin),
      () => {},
    );
    return () => {
      current = false;
    };
  }, [ready, skin]);

  return ready;
}

export type SavedAffection = { version: 1; affection: number; lastVisit: number };

/** A visit this long after the last one earns a greeting. */
const GREETING_GAP_MS = 30 * 60 * 1000;
export const MAX_AFFECTION = 999;

export function parseAffection(value: unknown): SavedAffection | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const { version, affection, lastVisit } = value as Record<string, unknown>;
  if (version !== 1) return null;
  if (typeof affection !== "number" || !Number.isFinite(affection)) return null;
  if (typeof lastVisit !== "number" || !Number.isFinite(lastVisit)) return null;
  return {
    version: 1,
    affection: Math.max(0, Math.min(MAX_AFFECTION, Math.floor(affection))),
    lastVisit,
  };
}

export function readAffection(key: string): SavedAffection | null {
  try {
    return parseAffection(JSON.parse(window.localStorage.getItem(key) ?? "null"));
  } catch {
    return null;
  }
}

export function writeAffection(key: string, affection: number, lastVisit = Date.now()): void {
  try {
    window.localStorage.setItem(key, JSON.stringify({ version: 1, affection, lastVisit }));
  } catch {
    // Affection is a nicety; the cat still works without storage.
  }
}

/** 0 stranger, 1 acquaintance, 2 friend, 3 best friend. */
export function affectionTier(affection: number): 0 | 1 | 2 | 3 {
  if (affection >= 15) return 3;
  if (affection >= 5) return 2;
  if (affection >= 1) return 1;
  return 0;
}

export const GREETINGS: Record<ReturnType<typeof affectionTier>, readonly string[]> = {
  0: ["oh. a new hooman", "who are you. do you have snacks", "hello, stranger"],
  1: ["you again. acceptable", "I remember you. vaguely", "back so soon?"],
  2: ["my hooman is back!", "I saved you a warm pixel", "there you are. I waited"],
  3: [
    "I missed you. don't tell anyone",
    "best hooman has returned",
    "finally. I have so much to tell you",
  ],
};

/** A greeting for a visitor, or null when they were here a moment ago. */
export function greetingFor(saved: SavedAffection | null, now = Date.now()): string | null {
  if (saved && now - saved.lastVisit < GREETING_GAP_MS) return null;
  const pool = GREETINGS[affectionTier(saved?.affection ?? 0)];
  return pool[Math.floor(Math.random() * pool.length)];
}

import type { CatRuntimeState } from "./types";

/** The sprite has ten frames per second; no need to wake on every screen refresh. */
export function startAnimationLoop(
  stateRef: { current: CatRuntimeState },
  frame: () => void,
): () => void {
  let timer: ReturnType<typeof setInterval> | undefined;
  const syncVisibility = () => {
    clearInterval(timer);
    timer = undefined;
    if (document.hidden) return;
    timer = setInterval(() => {
      if (!stateRef.current.paused && !stateRef.current.cfg.paused) frame();
    }, 100);
  };
  document.addEventListener("visibilitychange", syncVisibility);
  syncVisibility();
  return () => {
    clearInterval(timer);
    document.removeEventListener("visibilitychange", syncVisibility);
  };
}

import { SOUND_POOLS } from "../constants";
import type { CatActivityState, CatRuntimeState, OnekoSoundEvent } from "../types";
import type { CatAnimationDeps } from "./deps";

export function getActivityLabel(deps: CatAnimationDeps): CatActivityState {
  const s = deps.stateRef.current;
  if (s.grab && s.grab.phase !== "landed") {
    return "alert";
  }
  if (s.freerunMode) {
    return "freerun";
  }
  if (s.idleAnimation === "sleeping") {
    return "sleeping";
  }
  if (s.idleAnimation) {
    return s.idleAnimation;
  }
  if (s.idleTime > 0) {
    return "idle";
  }
  return "moving";
}

export function getBubbleStatus(s: CatRuntimeState) {
  if (s.bubbleVisible) {
    return "showing";
  }
  if (s.bubbleCooldown > 0) {
    return `cd ${s.bubbleCooldown}f`;
  }
  return "ready";
}

/** A full URL for this moment: the host's own clip, or a built-in file under soundBasePath. */
function pickSound(s: CatRuntimeState, event: OnekoSoundEvent): string | undefined {
  const custom = s.cfg.sounds[event];
  const pool = custom ?? SOUND_POOLS[event];
  const url = typeof pool === "string" ? pool : pool[Math.floor(Math.random() * pool.length)];
  if (!url || custom !== undefined) return url;
  return `${s.cfg.soundBasePath}/${url.slice(url.lastIndexOf("/") + 1)}`;
}

export function playSound(deps: CatAnimationDeps, event: OnekoSoundEvent) {
  const s = deps.stateRef.current;
  if (!s.cfg.meow || s.soundCooldown > 0) return;
  const url = pickSound(s, event);
  if (!url) return;
  const audio = new Audio(url);
  audio.volume = s.cfg.volume;
  s.soundCooldown = 20;
  audio.play().catch(() => {
    s.soundCooldown = 0;
  });
}

import { TILE } from "../constants";
import { leaderPosition } from "../pack";
import type { CatRuntimeState } from "../types";
import type { CatAnimationDeps } from "./deps";
import { petCat } from "./play";

/** Links and buttons the cat may sit on when the pointer rests over them. */
const PERCH_SELECTOR = "a[href],button,[role='button'],[data-oneko-perch]";
const PERCH_DELAY_MS = 700;
const NOT_TYPED_INPUTS = new Set([
  "button",
  "checkbox",
  "color",
  "file",
  "image",
  "radio",
  "range",
  "reset",
  "submit",
]);

/** How close the cat gets before it settles, depending on what it is after. */
export function stopDistance(s: CatRuntimeState): number {
  if (s.errand || s.perchTarget) return Math.min(s.cfg.followDistance, 8);
  if (s.leaderTarget) return Math.max(s.cfg.followDistance, TILE * s.cfg.scale);
  return s.cfg.followDistance;
}

/** Per-frame upkeep for page reactions; runs before the movement target is chosen. */
export function tickAttention(deps: CatAnimationDeps): void {
  const s = deps.stateRef.current;
  s.leaderTarget = leaderPosition(s);
  if (s.typingNap && s.cfg.sleepEnabled && s.idleAnimation !== "sleeping") {
    s.freerunMode = false;
    s.idleAnimation = "sleeping";
    s.idleAnimationFrame = 0;
    s.idleTime = Math.max(s.idleTime, 1);
  }
}

function isTypingTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  if (target.isContentEditable || target instanceof HTMLTextAreaElement) return true;
  return target instanceof HTMLInputElement && !NOT_TYPED_INPUTS.has(target.type);
}

function isTypingKey(event: KeyboardEvent): boolean {
  if (event.ctrlKey || event.metaKey || event.altKey) return false;
  return event.key.length === 1 || event.key === "Backspace" || event.key === "Delete";
}

function matchesFocusVisible(el: Element): boolean {
  try {
    return el.matches(":focus-visible");
  } catch {
    return true;
  }
}

/**
 * Listens to the page for typing, keyboard focus, and resting pointers. Options are read from
 * the runtime state on every event, so toggling them needs no restart.
 */
export function watchPage(deps: CatAnimationDeps): () => void {
  const s = () => deps.stateRef.current;
  let perchTimer: ReturnType<typeof setTimeout> | undefined;
  let napAt: { x: number; y: number } | null = null;

  const onKeyDown = (event: KeyboardEvent) => {
    const state = s();
    if (!state.cfg.napWhileTyping || !isTypingTarget(event.target) || !isTypingKey(event)) return;
    state.typingNap = true;
    state.perchTarget = null;
    napAt = { x: state.mousePosX, y: state.mousePosY };
  };

  const onMouseMove = (event: MouseEvent) => {
    const state = s();
    // Browsers can send mousemove without real movement, so wake only after the pointer travels.
    if (
      state.typingNap &&
      (!napAt || Math.hypot(event.clientX - napAt.x, event.clientY - napAt.y) > 4)
    ) {
      state.typingNap = false;
    }
    state.perchTarget = null;
    state.focusTarget = null;
    clearTimeout(perchTimer);
    if (!state.cfg.perchOnHover) return;
    const { clientX: x, clientY: y } = event;
    perchTimer = setTimeout(() => {
      const current = s();
      const target = document.elementFromPoint(x, y)?.closest(PERCH_SELECTOR);
      if (!current.cfg.perchOnHover || !target || target === deps.el) return;
      const rect = target.getBoundingClientRect();
      if (rect.width === 0 || rect.width > window.innerWidth * 0.6) return;
      current.perchTarget = {
        x: rect.left + rect.width / 2,
        y: Math.max(16, rect.top - (TILE * current.cfg.scale) / 2 + 4),
      };
    }, PERCH_DELAY_MS);
  };

  const onFocusIn = (event: FocusEvent) => {
    const state = s();
    const target = event.target;
    if (!state.cfg.followFocus || !(target instanceof Element) || target === deps.el) return;
    if (!matchesFocusVisible(target)) return;
    const rect = target.getBoundingClientRect();
    const reach = (TILE * state.cfg.scale) / 2 + 8;
    const below = rect.bottom + reach;
    // Its own target, so the cursor position (catches, laser, treats) stays the real pointer's.
    state.focusTarget = {
      x: Math.min(window.innerWidth - 16, Math.max(16, rect.left + rect.width / 2)),
      y: below < window.innerHeight - 16 ? below : Math.max(16, rect.top - reach),
    };
    state.perchTarget = null;
  };

  const onScroll = () => {
    s().perchTarget = null;
  };

  document.addEventListener("keydown", onKeyDown, true);
  document.addEventListener("mousemove", onMouseMove);
  document.addEventListener("focusin", onFocusIn);
  window.addEventListener("scroll", onScroll, { passive: true });
  return () => {
    clearTimeout(perchTimer);
    document.removeEventListener("keydown", onKeyDown, true);
    document.removeEventListener("mousemove", onMouseMove);
    document.removeEventListener("focusin", onFocusIn);
    window.removeEventListener("scroll", onScroll);
    const state = s();
    state.typingNap = false;
    state.perchTarget = null;
    state.focusTarget = null;
    state.held = false;
  };
}

const VISUALLY_HIDDEN =
  "position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap";

/** Turns the cat into a focusable "Pet the cat" button. It holds still while focused. */
export function makePettable(deps: CatAnimationDeps): () => void {
  const { el } = deps;
  const announcer = document.createElement("span");
  announcer.setAttribute("aria-live", "polite");
  announcer.style.cssText = VISUALLY_HIDDEN;
  el.appendChild(announcer);
  el.removeAttribute("aria-hidden");
  el.setAttribute("role", "button");
  el.setAttribute("aria-label", "Pet the cat");
  el.tabIndex = 0;
  let pets = 0;

  const onFocus = () => {
    deps.stateRef.current.held = true;
    if (matchesFocusVisible(el)) {
      el.style.outline = "2px solid var(--ring, Highlight)";
      el.style.outlineOffset = "2px";
    }
  };
  const onBlur = () => {
    deps.stateRef.current.held = false;
    el.style.outline = "";
  };
  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    event.preventDefault();
    if (!event.repeat) pet();
  };

  const pet = () => {
    petCat(deps);
    // Alternate the text so screen readers announce every pet, not just the first.
    announcer.textContent = ++pets % 2 ? "The cat purrs." : "The cat purrs happily.";
  };

  el.addEventListener("focus", onFocus);
  el.addEventListener("blur", onBlur);
  el.addEventListener("keydown", onKeyDown);
  return () => {
    el.removeEventListener("focus", onFocus);
    el.removeEventListener("blur", onBlur);
    el.removeEventListener("keydown", onKeyDown);
    announcer.remove();
    deps.stateRef.current.held = false;
  };
}

import {
  ALERT_MESSAGES,
  CIRCLE_LOOP_MESSAGES,
  IDLE_MESSAGES,
  MOUSE_LOOP_WINDING_TRIGGER,
  MOVING_MESSAGES,
  SCRATCHING_MESSAGES,
  SLEEPING_MESSAGES,
  TILE,
  TIRED_MESSAGES,
  WALL_SCRATCH_MESSAGES,
} from "../constants";
import { SEASON_MESSAGES } from "../seasons";
import type { CatAnimationDeps } from "./deps";

export function pickFromPool(deps: CatAnimationDeps, pool: readonly string[]) {
  const s = deps.stateRef.current;
  let idx = Math.floor(Math.random() * pool.length);
  if (idx === s.lastBubbleMsg) {
    idx = (idx + 1) % pool.length;
  }
  s.lastBubbleMsg = idx;
  return pool[idx];
}

function messageForIdleAnimation(deps: CatAnimationDeps): string | undefined {
  const s = deps.stateRef.current;

  if (s.idleAnimation === "sleeping") {
    return pickFromPool(deps, SLEEPING_MESSAGES);
  }
  if (typeof s.cfg.bubbleText === "string") {
    if (s.cfg.bubbleText.trim()) return s.cfg.bubbleText;
  } else {
    const thoughts = [...new Set(s.cfg.bubbleText.filter((text) => text.trim()))];
    if (thoughts.length) return pickFromPool(deps, thoughts);
  }
  if (s.idleAnimation === "tired") {
    return pickFromPool(deps, TIRED_MESSAGES);
  }
  if (s.idleAnimation === "scratchSelf") {
    return pickFromPool(deps, SCRATCHING_MESSAGES);
  }
  if (s.idleAnimation === "alert") {
    return pickFromPool(deps, ALERT_MESSAGES);
  }
  if (s.idleAnimation?.startsWith("scratchWall")) {
    return pickFromPool(deps, WALL_SCRATCH_MESSAGES);
  }

  return undefined;
}

function messageForActivity(deps: CatAnimationDeps): string {
  const s = deps.stateRef.current;
  const idleAnimationMessage = messageForIdleAnimation(deps);
  if (idleAnimationMessage) {
    return idleAnimationMessage;
  }
  if (s.season && Math.random() < 0.35) {
    return pickFromPool(deps, SEASON_MESSAGES[s.season]);
  }
  if (s.idleTime > 0) {
    return pickFromPool(deps, IDLE_MESSAGES);
  }
  if (Math.abs(s.mouseCircleWinding) >= MOUSE_LOOP_WINDING_TRIGGER) {
    return pickFromPool(deps, CIRCLE_LOOP_MESSAGES);
  }
  return pickFromPool(deps, MOVING_MESSAGES);
}

function pickBubbleMessage(deps: CatAnimationDeps) {
  return messageForActivity(deps);
}

/**
 * The one way a bubble appears. Automatic bubbles respect bubbleEnabled and never replace one
 * asked for with say(); forced bubbles always show. The text is only picked when it will show.
 */
export function presentBubble(
  deps: CatAnimationDeps,
  text: () => string,
  frames: number,
  { forced = false }: { forced?: boolean } = {},
): boolean {
  const s = deps.stateRef.current;
  if (!forced && (!s.cfg.bubbleEnabled || (s.bubbleForced && s.bubbleVisible))) return false;
  s.bubbleVisible = true;
  s.bubbleForced = forced;
  s.bubbleTimer = frames;
  s.bubbleCooldown = 0;
  deps.bubbleTextEl.textContent = text();
  deps.bubbleEl.style.opacity = "1";
  return true;
}

/** A thought that fits what the cat is doing. */
export function showBubble(deps: CatAnimationDeps, options?: { forced?: boolean }) {
  presentBubble(
    deps,
    () => pickBubbleMessage(deps),
    deps.stateRef.current.cfg.bubbleDisplayFrames,
    options,
  );
}

export function hideBubble(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.bubbleVisible = false;
  s.bubbleForced = false;
  deps.bubbleEl.style.opacity = "0";
  s.bubbleCooldown = s.cfg.bubbleCooldown;
}

function applyBubblePlacement(deps: CatAnimationDeps, showBelow: boolean) {
  deps.bubbleEl.style.transformOrigin = "top center";
  deps.bubbleEl.style.flexDirection = showBelow ? "column-reverse" : "column";
  deps.bubbleTail.style.cssText = showBelow
    ? "transform:scaleY(-1);margin-top:0;margin-bottom:-2px;"
    : "transform:none;margin-top:-2px;margin-bottom:0;";
}

function positionBubble(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const catX = Math.floor(s.nekoPosX);
  const catY = Math.floor(s.nekoPosY);
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const bubbleW = deps.bubbleEl.offsetWidth || deps.bubbleTextEl.offsetWidth || 100;
  const bubbleH = deps.bubbleEl.offsetHeight || 34;
  const bubbleScale = s.cfg.scale * s.cfg.bubbleScale;
  const margin = 6;
  const halfCat = (TILE * s.cfg.scale) / 2;

  const aboveY = Math.floor(catY - halfCat - 8 - bubbleH * bubbleScale);
  const belowY = Math.floor(catY + halfCat + 8);
  const showBelow =
    s.cfg.bubblePlacement === "below" ||
    (s.cfg.bubblePlacement === "auto" && aboveY < margin && catY < vh / 2);
  const top = Math.max(
    margin,
    Math.min(vh - margin - bubbleH * bubbleScale, showBelow ? belowY : aboveY),
  );
  deps.bubbleEl.style.top = `${Math.round(top)}px`;
  deps.bubbleEl.style.transform = `translateX(-50%) scale(${bubbleScale})`;
  applyBubblePlacement(deps, showBelow);

  const halfBubble = (bubbleW * bubbleScale) / 2;
  let left = catX;
  if (halfBubble * 2 > vw - margin * 2) {
    left = vw / 2;
  } else if (catX - halfBubble < margin) {
    left = margin + halfBubble;
  } else if (catX + halfBubble > vw - margin) {
    left = vw - margin - halfBubble;
  }
  deps.bubbleEl.style.left = `${Math.round(left)}px`;
}

function tickVisibleBubble(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.bubbleTimer -= 1;
  if (s.bubbleTimer <= 0) {
    hideBubble(deps);
  }
}

function tickBubbleCooldown(deps: CatAnimationDeps) {
  deps.stateRef.current.bubbleCooldown -= 1;
}

function shouldTriggerBubble(deps: CatAnimationDeps): boolean {
  const s = deps.stateRef.current;
  const idleFrameThreshold = Math.max(1, Math.round(s.cfg.idleThreshold / 100));
  const idleRate = s.cfg.bubbleChance * 0.16;
  const moveRate = s.cfg.bubbleChance * 0.01;
  const loopW = Math.abs(s.mouseCircleWinding);
  const loopComplaining = s.idleTime === 0 && loopW >= MOUSE_LOOP_WINDING_TRIGGER;
  const moveRateBoost = loopComplaining ? 4.2 : 1;

  if (s.idleTime > idleFrameThreshold && Math.random() < idleRate) {
    return true;
  }
  return s.idleTime === 0 && Math.random() < moveRate * moveRateBoost;
}

export function updateBubble(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (s.sayRequest) {
    // say() and data-oneko-say speak even when automatic bubbles are off.
    const { text, frames } = s.sayRequest;
    presentBubble(deps, () => text, frames, { forced: true });
    s.sayRequest = null;
  }
  if (!s.cfg.bubbleEnabled && !s.bubbleForced) {
    if (s.bubbleVisible) {
      hideBubble(deps);
    }
    return;
  }

  positionBubble(deps);

  if (s.bubbleVisible) {
    tickVisibleBubble(deps);
    return;
  }

  if (s.bubbleCooldown > 0) {
    tickBubbleCooldown(deps);
    return;
  }

  if (shouldTriggerBubble(deps)) {
    showBubble(deps);
  }
}

import { CELL_SIZE, debugColor } from "../constants";
import type { ObstacleRect, PathPoint } from "../types";
import { getActivityLabel, getBubbleStatus } from "./activity";
import type { CatAnimationDeps } from "./deps";

const SVG_NS = "http://www.w3.org/2000/svg";

function clearSVGGroup(deps: CatAnimationDeps, id: string) {
  const group = deps.debugSVG.querySelector(`#${id}`);
  if (group) {
    group.innerHTML = "";
  }
}

function updateBlockedCells(deps: CatAnimationDeps, grid: Uint8Array, cols: number, rows: number) {
  const group = deps.debugSVG.querySelector("#oneko-blocked");
  if (!group) {
    return;
  }
  group.innerHTML = "";
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      if (grid[r * cols + c] === 1) {
        const rect = document.createElementNS(SVG_NS, "rect");
        rect.setAttribute("x", String(c * CELL_SIZE + 0.5));
        rect.setAttribute("y", String(r * CELL_SIZE + 0.5));
        rect.setAttribute("width", String(CELL_SIZE - 1));
        rect.setAttribute("height", String(CELL_SIZE - 1));
        rect.setAttribute("fill", "none");
        rect.setAttribute("stroke", debugColor.dangerSoft);
        rect.setAttribute("stroke-width", "0.5");
        group.appendChild(rect);
      }
    }
  }
}

function updateObstacleOutlines(deps: CatAnimationDeps, rects: ObstacleRect[]) {
  const group = deps.debugSVG.querySelector("#oneko-obstacles");
  if (!group) {
    return;
  }
  group.innerHTML = "";
  for (const r of rects) {
    const rect = document.createElementNS(SVG_NS, "rect");
    rect.setAttribute("x", String(r.left));
    rect.setAttribute("y", String(r.top));
    rect.setAttribute("width", String(r.right - r.left));
    rect.setAttribute("height", String(r.bottom - r.top));
    rect.setAttribute("fill", "none");
    rect.setAttribute("stroke", debugColor.dangerSoft);
    rect.setAttribute("stroke-width", "0.5");
    rect.setAttribute("stroke-dasharray", "3 3");
    group.appendChild(rect);
  }
}

function updateDebugPath(deps: CatAnimationDeps, path: PathPoint[], catX: number, catY: number) {
  const group = deps.debugSVG.querySelector("#oneko-path");
  if (!group) {
    return;
  }
  group.innerHTML = "";
  if (path.length === 0) {
    return;
  }

  const points = `${catX},${catY} ${path.map((p) => `${p.x},${p.y}`).join(" ")}`;
  const line = document.createElementNS(SVG_NS, "polyline");
  line.setAttribute("points", points);
  line.setAttribute("fill", "none");
  line.setAttribute("stroke", debugColor.trail);
  line.setAttribute("stroke-width", "1.5");
  line.style.transition = "all 0.15s ease";
  group.appendChild(line);

  for (const pt of path) {
    const dot = document.createElementNS(SVG_NS, "circle");
    dot.setAttribute("cx", String(pt.x));
    dot.setAttribute("cy", String(pt.y));
    dot.setAttribute("r", "2");
    dot.setAttribute("fill", debugColor.trailDot);
    group.appendChild(dot);
  }
}

function updateDebugHUD(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const activity = getActivityLabel(deps);
  const stateColor = s.freerunMode ? debugColor.danger : debugColor.accent;
  const td = "padding:1px 0;";
  const labelTd = `${td}font-weight:bold;color:${debugColor.panelSubtle};padding-right:12px;`;
  const valueTd = `${td}text-align:right;`;
  const row = (label: string, value: string, color?: string) => {
    const valStyle = color ? `${valueTd}color:${color}` : valueTd;
    return `<tr><td style="${labelTd}">${label}</td><td style="${valStyle}">${value}</td></tr>`;
  };

  const speed = Math.hypot(s.nekoVelX, s.nekoVelY);
  const distToMouse = Math.hypot(s.mousePosX - s.nekoPosX, s.mousePosY - s.nekoPosY);

  deps.debugHUD.innerHTML = `<table style="border-collapse:collapse;width:100%">${[
    row("state", activity, stateColor),
    row("pos", `${Math.round(s.nekoPosX)}, ${Math.round(s.nekoPosY)}`),
    row("vel", `${s.nekoVelX.toFixed(1)}, ${s.nekoVelY.toFixed(1)}`),
    row("speed", speed.toFixed(1)),
    row("target", `${Math.round(s.mousePosX)}, ${Math.round(s.mousePosY)}`),
    row("dist", `${Math.round(distToMouse)}px`),
    row("idle", `${s.idleTime}f`),
    row("frame", `${s.frameCount}`),
    row("trail", `${s.currentPath.length} pts`),
    row("step", `${s.pathWaypointIdx}/${s.currentPath.length}`),
    row("obstacles", `${s.obstacleRects.length}`),
    row("grid", `${s.gridCols} x ${s.gridRows}`),
    row("freerun", s.freerunMode ? `${s.freerunTimer}f left` : "off"),
    row("bubble", getBubbleStatus(s)),
  ].join("")}</table>`;
}

export function createDebugRenderer(deps: CatAnimationDeps) {
  let lastBlockedGrid: Uint8Array | null = null;

  const renderDebug = () => {
    const s = deps.stateRef.current;
    if (s.grid !== lastBlockedGrid) {
      lastBlockedGrid = s.grid;
      if (s.grid) {
        updateBlockedCells(deps, s.grid, s.gridCols, s.gridRows);
      } else {
        clearSVGGroup(deps, "oneko-blocked");
      }
      updateObstacleOutlines(deps, s.obstacleRects);
    }
    updateDebugPath(deps, s.currentPath, s.nekoPosX, s.nekoPosY);
    updateDebugHUD(deps);
  };

  const maybeRenderDebug = () => {
    if (deps.stateRef.current.debugMode) {
      renderDebug();
    }
  };

  return { renderDebug, maybeRenderDebug };
}

import type { CatActivityState, CatLiveState, CatRuntimeState } from "../types";

export interface CatAnimationDeps {
  stateRef: { current: CatRuntimeState };
  el: HTMLDivElement;
  bubbleEl: HTMLDivElement;
  bubbleTextEl: HTMLDivElement;
  bubbleTail: HTMLDivElement;
  debugSVG: SVGSVGElement;
  debugHUD: HTMLDivElement;
  lastStateRef: { current: CatActivityState };
  onStateChangeRef: { current: ((state: CatActivityState) => void) | undefined };
  liveStateRef?: { current: CatLiveState };
  /** Seasonal hat drawn on the cat, repositioned with every sprite frame. */
  hat?: HTMLDivElement;
}

import { TILE } from "../constants";
import type { CatRuntimeState, PathPoint } from "../types";
import type { Errand } from "./play-types";

const clamp = (value: number, min: number, max: number) =>
  Math.max(min, Math.min(Math.max(min, max), value));

function visibleRect(el: Element): DOMRect | null {
  if (!el.isConnected) return null;
  const rect = el.getBoundingClientRect();
  if (rect.width === 0 || rect.height === 0) return null;
  if (rect.bottom < 0 || rect.right < 0 || rect.top > window.innerHeight) return null;
  if (rect.left > window.innerWidth) return null;
  return rect;
}

/**
 * Where an errand takes the cat, in viewport coordinates, or null when its element is gone or
 * off screen. Element targets are re-read every tick, so they follow scrolling and layout.
 */
export function errandPoint(s: CatRuntimeState, errand: Errand): PathPoint | null {
  const half = (TILE * s.cfg.scale) / 2;
  const maxX = window.innerWidth - 16;
  const maxY = window.innerHeight - 16;
  switch (errand.kind) {
    case "sit":
      return { x: s.nekoPosX, y: s.nekoPosY };
    case "treat":
      return errand.treat.eaten ? null : { x: errand.treat.x, y: errand.treat.y };
    case "goTo": {
      const { target } = errand;
      if (!(target instanceof Element))
        return { x: clamp(target.x, 16, maxX), y: clamp(target.y, 16, maxY) };
      const rect = visibleRect(target);
      if (!rect) return null;
      // Settle just below the element, or above it when there is no room below.
      const below = rect.bottom + half + 4;
      return {
        x: clamp(rect.left + rect.width / 2, 16, maxX),
        y: below < maxY ? below : clamp(rect.top - half - 4, 16, maxY),
      };
    }
    case "box": {
      const rect = visibleRect(errand.el);
      if (!rect) return null;
      return {
        x: clamp(rect.left + rect.width / 2, 16, maxX),
        y: clamp(Math.max(rect.top + half, rect.bottom - half - 2), 16, maxY),
      };
    }
    case "knock": {
      const rect = visibleRect(errand.el);
      if (!rect) return null;
      // Stand beside the element, feet level with its bottom, on the side it gets pushed from.
      const x = errand.direction === 1 ? rect.left - half * 0.75 : rect.right + half * 0.75;
      return {
        x: clamp(x, 16, maxX),
        y: clamp(Math.max(rect.top + half / 2, rect.bottom - half), 16, maxY),
      };
    }
  }
}

import { refreshZones, updateZoneTarget } from "../zone-runtime";
import { tickAttention } from "./attention";
import { createDebugRenderer } from "./debug-render";
import type { CatAnimationDeps } from "./deps";
import type { CatPlay } from "./play";
import { updateBubble } from "./bubbles";
import { tickLiveState } from "./frame/tick-live-state";
import { tickMovement } from "./frame/tick-movement";
import { tickPrelude } from "./frame/tick-prelude";
import { tickSounds } from "./frame/tick-sounds";

export function createFrameLoop(deps: CatAnimationDeps, play?: CatPlay) {
  const { maybeRenderDebug } = createDebugRenderer(deps);

  const frame = () => {
    const s = deps.stateRef.current;
    if (s.cfg.paused) return;
    if (!refreshZones(deps)) return;
    tickPrelude(s);
    play?.upkeep();
    tickAttention(deps);
    updateZoneTarget(s, window.innerWidth, window.innerHeight);
    const dist = Math.hypot(s.mousePosX - s.nekoPosX, s.mousePosY - s.nekoPosY);
    if (play?.tickGrab()) {
      updateBubble(deps);
    } else {
      tickMovement(deps, dist);
      play?.tickErrand();
    }
    maybeRenderDebug();
    const currentState = tickSounds(deps);
    tickLiveState(deps, dist, currentState);
  };

  return frame;
}

import type { CatRuntimeState } from "../../types";
import { stopDistance } from "../attention";

export function interruptIdleIfChasing(s: CatRuntimeState, dist: number) {
  // Wake only when the target is clearly out of reach, so a cat napping beside its lead stays asleep.
  const reach = Math.max(32, stopDistance(s) + 12);
  if (s.idleAnimation && dist > reach && !s.stateLocked && !s.noFollow) {
    s.idleAnimation = null;
    s.idleAnimationFrame = 0;
    s.idleTime = 0;
  }
}

import { playSound } from "../activity";
import type { CatAnimationDeps } from "../deps";

export function tickLaser(deps: CatAnimationDeps, dist: number) {
  const s = deps.stateRef.current;
  if (!s.cfg.laserPointer) {
    return;
  }

  const close = dist < s.cfg.followDistance + 4;
  if (close && !s.laserCaught) {
    s.laserCaught = true;
    playSound(deps, "eat");
  } else if (!close && dist > s.cfg.followDistance + 24) {
    s.laserCaught = false;
  }
}

import type { CatActivityState } from "../../types";
import type { CatAnimationDeps } from "../deps";

export function tickLiveState(
  deps: CatAnimationDeps,
  dist: number,
  currentState: CatActivityState,
) {
  if (!deps.liveStateRef?.current) {
    return;
  }

  const s = deps.stateRef.current;
  const ls = deps.liveStateRef.current;
  ls.state = currentState;
  ls.posX = s.nekoPosX;
  ls.posY = s.nekoPosY;
  ls.velMag = Math.hypot(s.nekoVelX, s.nekoVelY);
  ls.idleTime = s.idleTime;
  ls.distToMouse = dist;
  ls.frameCount = s.frameCount;
  ls.freerunActive = s.freerunMode;
  ls.freerunTimer = s.freerunTimer;
  ls.bubbleVisible = s.bubbleVisible;
  ls.pathLength = s.currentPath.length;
  ls.obstacleCount = s.obstacleRects.length;
}

import { updateBubble } from "../bubbles";
import type { CatAnimationDeps } from "../deps";
import { recalcPathIfNeeded, refreshGridIfNeeded } from "../grid";
import { freezeLockedState, updateIdleAnimation } from "../idle";
import { followPath } from "../movement";
import { interruptIdleIfChasing } from "./interrupt-idle";
import { tickLaser } from "./tick-laser";

export function tickMovement(deps: CatAnimationDeps, dist: number) {
  const s = deps.stateRef.current;
  refreshGridIfNeeded(deps);
  const target = s.zoneState.movementTarget;
  const targetDistance = Math.hypot(target.x - s.nekoPosX, target.y - s.nekoPosY);
  interruptIdleIfChasing(s, targetDistance);
  recalcPathIfNeeded(deps);
  updateBubble(deps);
  tickLaser(deps, dist);

  if (!updateIdleAnimation(deps) && !freezeLockedState(deps)) {
    followPath(deps, targetDistance);
  }
}

import { MOUSE_LOOP_WINDING_DECAY } from "../../constants";
import type { CatRuntimeState } from "../../types";

export function tickPrelude(s: CatRuntimeState) {
  s.frameCount += 1;
  s.mouseCircleWinding *= MOUSE_LOOP_WINDING_DECAY;
  if (Math.abs(s.mouseCircleWinding) < 0.35) {
    s.mouseCircleWinding = 0;
    s.loopPrevAngle = null;
  }
  s.soundCooldown = Math.max(0, s.soundCooldown - 1);
}

import type { CatActivityState, OnekoSoundEvent } from "../../types";
import { getActivityLabel, playSound } from "../activity";
import type { CatAnimationDeps } from "../deps";

function soundEvent(state: CatActivityState): OnekoSoundEvent {
  return state.startsWith("scratchWall") ? "scratchWall" : (state as OnekoSoundEvent);
}

function tickAmbientSounds(deps: CatAnimationDeps, currentState: CatActivityState) {
  const s = deps.stateRef.current;
  const { idleTime, frameCount } = s;

  if (currentState === "idle" && idleTime > 0 && idleTime % 60 === 0) {
    playSound(deps, "idle");
  } else if (currentState === "sleeping" && frameCount % 100 === 0) {
    playSound(deps, "sleeping");
  } else if (currentState === "moving" && frameCount % 80 === 0) {
    playSound(deps, "moving");
  }
}

export function tickSounds(deps: CatAnimationDeps): CatActivityState {
  const currentState = getActivityLabel(deps);

  if (currentState !== deps.lastStateRef.current) {
    deps.lastStateRef.current = currentState;
    deps.onStateChangeRef.current?.(currentState);
    if (currentState === "sleeping") deps.stateRef.current.handlers.onSleep?.();
    playSound(deps, soundEvent(currentState));
  }

  tickAmbientSounds(deps, currentState);
  return currentState;
}

import {
  CELL_SIZE,
  OBSTACLE_INTERVAL,
  PATH_RECALC_INTERVAL,
  PATH_RECALC_MOUSE_CELLS,
} from "../constants";
import { buildGrid, collectObstacles } from "../pathfinding";
import type { CatAnimationDeps } from "./deps";
import { recalculatePath } from "./movement";

export function refreshGridIfNeeded(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (s.frameCount - s.lastObstacleRefresh < OBSTACLE_INTERVAL) {
    return;
  }
  const softObstacles = collectObstacles().filter(
    (rect) =>
      !s.zoneState.favorites.some(
        ({ rect: favorite }) =>
          rect.left >= favorite.left &&
          rect.right <= favorite.right &&
          rect.top >= favorite.top &&
          rect.bottom <= favorite.bottom,
      ),
  );
  s.obstacleRects = [...softObstacles, ...s.zoneState.blocked];
  s.lastObstacleRefresh = s.frameCount;
  s.gridCols = Math.ceil(window.innerWidth / CELL_SIZE);
  s.gridRows = Math.ceil(window.innerHeight / CELL_SIZE);
  s.grid = buildGrid(s.obstacleRects, s.gridCols, s.gridRows);
  s.lastPathRecalcFrame = -PATH_RECALC_INTERVAL;
}

export function recalcPathIfNeeded(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const mouseCol = Math.floor(s.zoneState.movementTarget.x / CELL_SIZE);
  const mouseRow = Math.floor(s.zoneState.movementTarget.y / CELL_SIZE);
  const mouseMoved =
    Math.abs(mouseCol - s.lastPathTargetCol) > PATH_RECALC_MOUSE_CELLS ||
    Math.abs(mouseRow - s.lastPathTargetRow) > PATH_RECALC_MOUSE_CELLS;
  if (s.frameCount - s.lastPathRecalcFrame >= PATH_RECALC_INTERVAL || mouseMoved) {
    recalculatePath(deps);
  }
}

import { defaultSpriteSets, IDLE_ANIMATION_DURATIONS, SLEEPING_MESSAGES } from "../constants";
import { napmateNearby } from "../pack";
import type { CatRuntimeState, IdleActivityState } from "../types";
import { pickFromPool } from "./bubbles";
import type { CatAnimationDeps } from "./deps";
import { clearRotation, setSprite } from "./sprites";

function idleFrameThreshold(s: CatRuntimeState) {
  return Math.max(1, Math.round((s.cfg.idleThreshold * s.mood.idle) / 100));
}

function wallScratchAnimations(s: CatRuntimeState): IdleActivityState[] {
  return [
    s.nekoPosX <= 18 && "scratchWallW",
    s.nekoPosX >= window.innerWidth - 18 && "scratchWallE",
    s.nekoPosY <= 18 && "scratchWallN",
    s.nekoPosY >= window.innerHeight - 18 && "scratchWallS",
  ].filter(Boolean) as IdleActivityState[];
}

function pickRandomIdleAnimation(s: CatRuntimeState): IdleActivityState {
  const available: IdleActivityState[] = [
    "scratchSelf",
    ...(s.cfg.sleepEnabled ? ["tired" as const] : []),
    ...wallScratchAnimations(s),
  ];
  return available[Math.floor(Math.random() * available.length)];
}

function startSleepingAnimation(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.idleAnimation = "sleeping";
  if (s.bubbleVisible) {
    deps.bubbleTextEl.textContent = pickFromPool(deps, SLEEPING_MESSAGES);
  }
}

export function maybeStartIdleAnimation(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const threshold = idleFrameThreshold(s);
  if (s.idleAnimation != null || s.idleTime < threshold || Math.random() >= 0.1) {
    return;
  }

  s.idleAnimationFrame = 0;
  // Sleep is catching: a cat resting beside a napping friend dozes off without the usual wait.
  if (s.cfg.sleepEnabled && (s.idleTime > threshold * 3 || napmateNearby(s))) {
    startSleepingAnimation(deps);
    return;
  }

  s.idleAnimation = pickRandomIdleAnimation(s);
}

function computeIdleSpriteIndex(
  animName: IdleActivityState,
  frame: number,
  animationSpeed: number,
): number {
  const sprites = defaultSpriteSets[animName as keyof typeof defaultSpriteSets];
  const baseDuration = IDLE_ANIMATION_DURATIONS[animName] ?? (sprites ? sprites.length * 8 : 8);
  const duration = Math.max(1, Math.round(baseDuration / animationSpeed));
  const frameCount = sprites?.length || 1;
  const framesPerSprite = Math.max(1, Math.floor(duration / frameCount));
  return Math.floor(frame / framesPerSprite) % frameCount;
}

function getIdleAnimationDuration(animName: IdleActivityState, animationSpeed: number): number {
  const sprites = defaultSpriteSets[animName as keyof typeof defaultSpriteSets];
  const baseDuration = IDLE_ANIMATION_DURATIONS[animName] ?? (sprites ? sprites.length * 8 : 8);
  return Math.max(1, Math.round(baseDuration / animationSpeed));
}

function resetOrLoopIdleAnimation(
  s: CatRuntimeState,
  animName: IdleActivityState,
  duration: number,
) {
  if (s.idleAnimationFrame < duration || animName === "sleeping") {
    return;
  }

  if (s.stateLocked || s.noFollow) {
    s.idleAnimationFrame = 0;
    return;
  }

  s.idleAnimation = null;
  s.idleAnimationFrame = 0;
}

export function updateIdleAnimation(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (!s.cfg.sleepEnabled && (s.idleAnimation === "sleeping" || s.idleAnimation === "tired")) {
    s.idleAnimation = null;
    s.idleAnimationFrame = 0;
    s.idleTime = 0;
  }
  if (!s.idleAnimation) {
    return false;
  }

  const animName = s.idleAnimation;
  const spriteIndex = computeIdleSpriteIndex(animName, s.idleAnimationFrame, s.cfg.animationSpeed);
  setSprite(deps, animName, spriteIndex);
  clearRotation(deps);
  s.idleAnimationFrame += 1;
  resetOrLoopIdleAnimation(s, animName, getIdleAnimationDuration(animName, s.cfg.animationSpeed));
  return true;
}

export function freezeLockedState(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (!(s.stateLocked || s.noFollow) || (s.freerunMode && !s.noFollow)) {
    return false;
  }

  s.nekoVelX *= 0.5;
  s.nekoVelY *= 0.5;
  s.idleTime = Math.max(s.idleTime, 1);
  setSprite(deps, "idle", s.frameCount);
  clearRotation(deps);
  return true;
}

import { MOUSE_LOOP_MIN_STEP, MOUSE_LOOP_WINDING_CAP } from "../constants";
import type { CatAnimationDeps } from "./deps";

export function createMouseMoveHandler(deps: CatAnimationDeps) {
  return (ev: MouseEvent) => {
    const mx = ev.clientX;
    const my = ev.clientY;
    const s = deps.stateRef.current;
    const px = s.mousePosX;
    const py = s.mousePosY;
    const dx = mx - px;
    const dy = my - py;
    const dist = Math.hypot(dx, dy);
    if (dist >= MOUSE_LOOP_MIN_STEP) {
      const ang = Math.atan2(dy, dx);
      if (s.loopPrevAngle !== null) {
        let d = ang - s.loopPrevAngle;
        while (d > Math.PI) {
          d -= 2 * Math.PI;
        }
        while (d < -Math.PI) {
          d += 2 * Math.PI;
        }
        s.mouseCircleWinding += d;
        if (s.mouseCircleWinding > MOUSE_LOOP_WINDING_CAP) {
          s.mouseCircleWinding = MOUSE_LOOP_WINDING_CAP;
        } else if (s.mouseCircleWinding < -MOUSE_LOOP_WINDING_CAP) {
          s.mouseCircleWinding = -MOUSE_LOOP_WINDING_CAP;
        }
      }
      s.loopPrevAngle = ang;
    }
    s.mousePosX = mx;
    s.mousePosY = my;
  };
}

import { constrainZoneMovement } from "../zones";
import {
  CELL_SIZE,
  FREERUN_MESSAGES,
  MAX_VEL_FACTOR,
  STEER_LERP,
  TILE,
  WAYPOINT_REACH_DIST,
} from "../constants";
import { findRoute, nearestWalkable, worldToCell } from "../pathfinding";
import { stopDistance } from "./attention";
import type { CatAnimationDeps } from "./deps";
import { maybeStartIdleAnimation } from "./idle";
import { clearRotation, directionFromDelta, setSprite } from "./sprites";
import { presentBubble } from "./bubbles";

export function recalculatePath(deps: CatAnimationDeps): void {
  const s = deps.stateRef.current;
  const { grid, gridCols: cols, gridRows: rows } = s;
  if (!grid || cols === 0 || rows === 0) {
    s.currentPath = [];
    return;
  }

  const catCell = nearestWalkable(
    worldToCell(s.nekoPosX, s.nekoPosY, cols, rows),
    grid,
    cols,
    rows,
  );
  const mouseCell = nearestWalkable(
    worldToCell(s.zoneState.movementTarget.x, s.zoneState.movementTarget.y, cols, rows),
    grid,
    cols,
    rows,
  );

  s.currentPath = findRoute(catCell, mouseCell, grid, cols, rows);
  s.pathWaypointIdx = 0;
  s.lastPathRecalcFrame = s.frameCount;
  s.lastPathTargetCol = Math.floor(s.zoneState.movementTarget.x / CELL_SIZE);
  s.lastPathTargetRow = Math.floor(s.zoneState.movementTarget.y / CELL_SIZE);
}

function getNextWaypointTarget(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  const { currentPath: path } = s;
  if (path.length === 0) {
    return { x: s.zoneState.movementTarget.x, y: s.zoneState.movementTarget.y };
  }
  while (s.pathWaypointIdx < path.length - 1) {
    const wp = path[s.pathWaypointIdx];
    if (Math.hypot(wp.x - s.nekoPosX, wp.y - s.nekoPosY) < WAYPOINT_REACH_DIST) {
      s.pathWaypointIdx++;
    } else {
      break;
    }
  }
  return path[s.pathWaypointIdx];
}

function moveToward(deps: CatAnimationDeps, targetX: number, targetY: number) {
  const s = deps.stateRef.current;
  const dx = targetX - s.nekoPosX;
  const dy = targetY - s.nekoPosY;
  const dist = Math.hypot(dx, dy);
  if (dist < 1) {
    s.nekoVelX *= 0.5;
    s.nekoVelY *= 0.5;
    return;
  }
  const currentSpeed = s.cfg.speed * s.mood.speed;
  s.nekoVelX += ((dx / dist) * currentSpeed - s.nekoVelX) * STEER_LERP;
  s.nekoVelY += ((dy / dist) * currentSpeed - s.nekoVelY) * STEER_LERP;
  const velMag = Math.hypot(s.nekoVelX, s.nekoVelY);
  const maxVel = currentSpeed * MAX_VEL_FACTOR;
  const clampedMag = Math.min(velMag, maxVel);
  if (velMag > maxVel) {
    s.nekoVelX = (s.nekoVelX / velMag) * maxVel;
    s.nekoVelY = (s.nekoVelY / velMag) * maxVel;
  }
  const from = { x: s.nekoPosX, y: s.nekoPosY };
  const proposed = {
    x: Math.max(16, Math.min(window.innerWidth - 16, s.nekoPosX + s.nekoVelX)),
    y: Math.max(16, Math.min(window.innerHeight - 16, s.nekoPosY + s.nekoVelY)),
  };
  const safe = constrainZoneMovement(from, proposed, s.zoneState.blocked);
  if (safe.x !== proposed.x || safe.y !== proposed.y) {
    s.nekoVelX = 0;
    s.nekoVelY = 0;
  }
  if (safe.x === from.x && safe.y === from.y && (safe.x !== proposed.x || safe.y !== proposed.y)) {
    restNearCursor(deps);
    return;
  }
  s.nekoPosX = safe.x;
  s.nekoPosY = safe.y;
  s.nekoPosX = Math.max(16, Math.min(window.innerWidth - 16, s.nekoPosX));
  s.nekoPosY = Math.max(16, Math.min(window.innerHeight - 16, s.nekoPosY));
  deps.el.style.left = `${Math.floor(s.nekoPosX - TILE / 2)}px`;
  deps.el.style.top = `${Math.floor(s.nekoPosY - TILE / 2)}px`;
  const dir = directionFromDelta(s.nekoVelX, s.nekoVelY) ?? "idle";
  setSprite(deps, dir, s.frameCount);
  if (clampedMag > 0.5 && s.cfg.rotationAmount > 0) {
    const velAngle = Math.atan2(s.nekoVelY, s.nekoVelX) * (180 / Math.PI);
    s.currentRotation = (velAngle / 180) * s.cfg.rotationAmount;
  } else {
    s.currentRotation = 0;
  }
  deps.el.style.transform = `scale(${s.cfg.scale}) rotate(${s.currentRotation}deg)`;
  s.idleTime = 0;
}

function pickFreerunMessage(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  let idx = Math.floor(Math.random() * FREERUN_MESSAGES.length);
  if (idx === s.lastFreerunMsg) {
    idx = (idx + 1) % FREERUN_MESSAGES.length;
  }
  s.lastFreerunMsg = idx;
  return FREERUN_MESSAGES[idx];
}

function enterFreerun(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.freerunMode = true;
  s.freerunTimer = s.cfg.freerunDuration;
  presentBubble(deps, () => pickFreerunMessage(deps), s.cfg.freerunDuration);
}

function tickFreerun(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  s.freerunTimer -= 1;
  if (s.freerunTimer <= 0) {
    const keepAlive = s.stateLocked;
    s.freerunMode = keepAlive;
    if (keepAlive) {
      s.freerunTimer = s.cfg.freerunDuration;
    }
  }
  moveToward(deps, s.zoneState.movementTarget.x, s.zoneState.movementTarget.y);
}

function restNearCursor(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  setSprite(deps, "idle", s.frameCount);
  clearRotation(deps);
  s.nekoVelX *= 0.5;
  s.nekoVelY *= 0.5;
  s.idleTime += 1;
  if (!(s.stateLocked || s.noFollow)) {
    s.freerunMode = false;
  }
  maybeStartIdleAnimation(deps);
}

function chaseCursor(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (s.freerunMode) {
    tickFreerun(deps);
    return;
  }
  if (!s.noFollow && !s.errand && Math.random() < s.cfg.freerunChance * s.mood.freerun) {
    enterFreerun(deps);
    moveToward(deps, s.zoneState.movementTarget.x, s.zoneState.movementTarget.y);
    return;
  }
  const target = getNextWaypointTarget(deps);
  moveToward(deps, target.x, target.y);
}

export function followPath(deps: CatAnimationDeps, overallDist: number) {
  const s = deps.stateRef.current;
  const lastWaypoint = s.currentPath.at(-1);
  const stop = stopDistance(s);
  const reachedPathEnd =
    !s.freerunMode &&
    lastWaypoint &&
    s.pathWaypointIdx === s.currentPath.length - 1 &&
    Math.hypot(lastWaypoint.x - s.nekoPosX, lastWaypoint.y - s.nekoPosY) < stop;
  if (overallDist < stop || reachedPathEnd) {
    restNearCursor(deps);
    return;
  }
  chaseCursor(deps);
}

import type { Treat } from "../treats";

export type PointLike = { x: number; y: number };

/** Something the cat goes off to do instead of chasing the cursor. */
export type Errand =
  | {
      kind: "goTo";
      target: Element | PointLike;
      frames: number;
      arrived: boolean;
      resolve?: (arrived: boolean) => void;
    }
  | { kind: "sit" }
  | { kind: "treat"; treat: Treat; frames: number }
  | { kind: "box"; el: Element; frames: number; arrived: boolean }
  | {
      kind: "knock";
      el: Element;
      frames: number;
      phase: "approach" | "stare";
      /** 1 pushes the element to the right, -1 to the left. */
      direction: 1 | -1;
    };

export type GrabState =
  | {
      phase: "held";
      samples: { x: number; y: number; t: number }[];
      startT: number;
      travel: number;
    }
  | { phase: "flying"; vx: number; vy: number; spin: number; hard: boolean }
  | { phase: "landed"; frames: number };

/** Multipliers from the visitor's clock; all 1 when timeOfDay is off. */
export type Mood = { speed: number; freerun: number; idle: number };

import {
  affectionTier,
  greetingFor,
  MAX_AFFECTION,
  readAffection,
  writeAffection,
} from "../affection";
import { PET_MESSAGES, TILE } from "../constants";
import { moodForHour, NEUTRAL_MOOD } from "../mood";
import { isNearestCat } from "../pack";
import {
  BOX_MESSAGES,
  FOND_PET_MESSAGES,
  HELD_MESSAGES,
  KNOCK_MESSAGES,
  KNOCK_STARE_MESSAGES,
  TOSS_HARD_MESSAGES,
  TOSS_SOFT_MESSAGES,
  TREAT_MESSAGES,
} from "../play-messages";
import { HAT_HEIGHT, HAT_WIDTH, hatSVG, resolveSeason } from "../seasons";
import { dropTreat, eatTreat, nearestTreat, type Treat } from "../treats";
import { constrainZoneMovement, containsPoint } from "../zones";
import type { CatRuntimeState } from "../types";
import { playSound } from "./activity";
import { pickFromPool, presentBubble } from "./bubbles";
import type { CatAnimationDeps } from "./deps";
import { errandPoint } from "./errand-point";
import { clearRotation, setSprite } from "./sprites";

/** Ticks between calendar and clock checks (one minute at 10fps). */
const CLOCK_CHECK_FRAMES = 600;
/** Ticks between looks for a box or something to knock over. */
const ERRAND_CHECK_FRAMES = 50;
const ERRAND_CHANCE = 0.25;
const ERRAND_REST_FRAMES = 300;
const BOX_NAP_FRAMES = 150;
const KNOCK_STARE_FRAMES = 12;
const KNOCKED_DOWN_MS = 5000;
/** Release speed in CSS pixels per millisecond. */
const MAX_TOSS_SPEED = 3;
const HARD_TOSS_SPEED = 1.6;
const TYPING_TARGETS =
  "a,button,input,select,textarea,label,summary,[role='button'],[contenteditable]";

/** Show a bubble now, when automatic bubbles are allowed. */
function speak(deps: CatAnimationDeps, pool: readonly string[]) {
  presentBubble(
    deps,
    () => pickFromPool(deps, pool),
    deps.stateRef.current.cfg.bubbleDisplayFrames,
  );
}

function bumpAffection(s: CatRuntimeState): number {
  s.affection = Math.min(MAX_AFFECTION, s.affection + 1);
  if (s.cfg.affection) writeAffection(s.affectionKey, s.affection);
  return s.affection;
}

/** Wake the cat from whatever it was doing, so a reaction reads clearly. */
function rouse(s: CatRuntimeState) {
  s.typingNap = false;
  s.freerunMode = false;
  s.idleAnimation = null;
  s.idleAnimationFrame = 0;
  s.idleTime = Math.max(s.idleTime, 1);
}

/** Pet the cat: a purr, a bubble, and a little more affection. */
export function petCat(deps: CatAnimationDeps): void {
  const s = deps.stateRef.current;
  rouse(s);
  const affection = bumpAffection(s);
  speak(deps, s.cfg.affection && affectionTier(affection) >= 2 ? FOND_PET_MESSAGES : PET_MESSAGES);
  playSound(deps, "pet");
  s.handlers.onPet?.({ affection });
}

const knocked = new Map<Element, { animation: Animation; tidy: ReturnType<typeof setTimeout> }>();

/** Push an element off its shelf. It lies at the bottom of the screen for a while, then returns. */
function knockOver(el: Element, direction: 1 | -1) {
  if (knocked.has(el) || !(el instanceof HTMLElement || el instanceof SVGElement)) return;
  const rect = el.getBoundingClientRect();
  const fall = Math.max(0, window.innerHeight - rect.bottom - 4);
  const animation = el.animate(
    [
      { transform: "none", offset: 0 },
      {
        transform: `translateX(${direction * 6}px) rotate(${direction * 12}deg)`,
        offset: 0.25,
      },
      {
        transform: `translate(${direction * 48}px, ${fall}px) rotate(${direction * 100}deg)`,
        offset: 1,
      },
    ],
    {
      duration: 700,
      easing: "cubic-bezier(0.5, 0, 0.9, 0.6)",
      fill: "forwards",
    },
  );
  const tidy = setTimeout(() => {
    // A hooman tidied up.
    animation.playbackRate = 2;
    animation.reverse();
    const forget = () => {
      if (knocked.get(el)?.animation === animation) knocked.delete(el);
    };
    animation.finished.then(() => {
      animation.cancel();
      forget();
    }, forget);
  }, KNOCKED_DOWN_MS);
  knocked.set(el, { animation, tidy });
}

/** Put every knocked-over element back, for when the last cat leaves. */
export function restoreKnocked(): void {
  for (const { animation, tidy } of knocked.values()) {
    clearTimeout(tidy);
    animation.cancel();
  }
  knocked.clear();
}

function isVisible(el: Element) {
  const rect = el.getBoundingClientRect();
  return (
    rect.width > 0 &&
    rect.height > 0 &&
    rect.top >= 0 &&
    rect.left >= 0 &&
    rect.bottom <= window.innerHeight &&
    rect.right <= window.innerWidth
  );
}

const handledEvents = new WeakSet<Event>();

/** True when a viewport point is on a run of text rather than empty space. */
function isOverText(x: number, y: number): boolean {
  const node = document.caretRangeFromPoint?.(x, y)?.startContainer;
  if (!node || node.nodeType !== Node.TEXT_NODE || !node.textContent?.trim()) return false;
  const range = document.createRange();
  range.selectNodeContents(node);
  return [...range.getClientRects()].some(
    (rect) => x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom,
  );
}

export function createPlay(deps: CatAnimationDeps) {
  const s = () => deps.stateRef.current;
  const { el } = deps;
  let seasonKey = "";
  let seasonCheckedFrame = -Infinity;
  let grabbable: boolean | null = null;
  let flight = 0;
  let sayTarget: Element | null = null;
  let sayTimer: ReturnType<typeof setTimeout> | undefined;
  /** Treats this cat could not reach, for example behind a keep-out zone. */
  const unreachable = new WeakSet<Treat>();

  const wearHat = () => {
    const state = s();
    const key = String(state.cfg.seasonal);
    if (key === seasonKey && state.frameCount - seasonCheckedFrame < CLOCK_CHECK_FRAMES) return;
    seasonKey = key;
    seasonCheckedFrame = state.frameCount;
    const season = resolveSeason(state.cfg.seasonal);
    if (season === state.season && (deps.hat || !season)) return;
    state.season = season;
    deps.hat?.remove();
    deps.hat = undefined;
    if (!season) return;
    const hat = document.createElement("div");
    hat.setAttribute("data-oneko-hat", season);
    hat.style.cssText = `position:absolute;left:0;top:0;width:${HAT_WIDTH}px;height:${HAT_HEIGHT}px;pointer-events:none;display:none`;
    hat.innerHTML = hatSVG(season);
    el.appendChild(hat);
    deps.hat = hat;
  };

  const readClock = () => {
    const state = s();
    if (!state.cfg.timeOfDay) {
      state.mood = NEUTRAL_MOOD;
      state.moodCheckedFrame = -Infinity;
    } else if (state.frameCount - state.moodCheckedFrame >= CLOCK_CHECK_FRAMES) {
      state.mood = moodForHour(new Date().getHours());
      state.moodCheckedFrame = state.frameCount;
    }
  };

  const greet = () => {
    const state = s();
    if (!state.cfg.affection) {
      state.affectionLoaded = false;
      return;
    }
    if (state.affectionLoaded) return;
    state.affectionLoaded = true;
    const saved = readAffection(state.affectionKey);
    state.affection = Math.max(state.affection, saved?.affection ?? 0);
    const greeting = greetingFor(saved);
    writeAffection(state.affectionKey, state.affection);
    if (greeting && state.cfg.bubbleEnabled)
      state.sayRequest = {
        text: greeting,
        frames: state.cfg.bubbleDisplayFrames,
      };
  };

  const syncGrabbable = () => {
    const on = s().cfg.grabbable;
    if (on === grabbable) return;
    grabbable = on;
    el.style.pointerEvents = on ? "auto" : "none";
    el.style.cursor = on ? "grab" : "";
    el.style.touchAction = on ? "none" : "";
    if (!on) el.removeAttribute("title");
    else if (!el.hasAttribute("aria-label")) el.title = "Drag to toss, click to pet";
  };

  /** Look for a treat to eat, or now and then a box to sit in or something to knock over. */
  const chooseErrand = () => {
    const state = s();
    if (state.grab || !state.cfg.followCursor || state.typingNap || state.held) return;
    const current = state.errand?.kind;
    if (current === "goTo" || current === "sit") return;
    const treat = nearestTreat(state.nekoPosX, state.nekoPosY, (item) => unreachable.has(item));
    if (treat && current !== "treat") {
      rouse(state);
      state.errand = { kind: "treat", treat, frames: 0 };
      return;
    }
    if (state.errand || state.cfg.laserPointer || state.perchTarget || state.zoneState.targetId)
      return;
    if (--state.errandCooldown > 0) return;
    state.errandCooldown = ERRAND_CHECK_FRAMES;
    if (state.idleTime === 0 || Math.random() >= ERRAND_CHANCE) return;
    const size = TILE * state.cfg.scale;
    const boxes = [...document.querySelectorAll("[data-oneko-box]")].filter((box) => {
      const rect = box.getBoundingClientRect();
      return isVisible(box) && rect.width >= size * 0.75 && rect.height >= size * 0.5;
    });
    const knockables = [...document.querySelectorAll("[data-oneko-knockable]")].filter(
      (item) => isVisible(item) && !knocked.has(item),
    );
    const pick = [...boxes, ...knockables][
      Math.floor(Math.random() * (boxes.length + knockables.length))
    ];
    if (!pick) return;
    if (boxes.includes(pick)) {
      state.errand = { kind: "box", el: pick, frames: 0, arrived: false };
    } else {
      const rect = pick.getBoundingClientRect();
      state.errand = {
        kind: "knock",
        el: pick,
        frames: 0,
        phase: "approach",
        // Approach from the side the cat is already on, then push the other way.
        direction: state.nekoPosX <= rect.left + rect.width / 2 ? 1 : -1,
      };
    }
  };

  /** Per-tick upkeep before the movement target is chosen. */
  const upkeep = () => {
    const state = s();
    wearHat();
    readClock();
    greet();
    syncGrabbable();
    if (state.petRequest) {
      state.petRequest = false;
      petCat(deps);
    }
    chooseErrand();
  };

  const endErrand = (cooldown = 0) => {
    const state = s();
    state.errand = null;
    if (cooldown) state.errandCooldown = cooldown;
  };

  /** Arrivals and timeouts for the current errand, after the cat has moved. */
  const tickErrand = () => {
    const state = s();
    const errand = state.errand;
    const chasingCursor =
      !errand &&
      state.cfg.followCursor &&
      !state.typingNap &&
      !state.held &&
      !state.perchTarget &&
      !state.focusTarget &&
      !state.leaderTarget &&
      !state.zoneState.targetId;
    const toCursor = Math.hypot(state.mousePosX - state.nekoPosX, state.mousePosY - state.nekoPosY);
    if (!chasingCursor) state.chasingFar = false;
    else if (toCursor > 160 && state.idleTime === 0) state.chasingFar = true;
    else if (state.chasingFar && state.idleTime > 0) {
      state.chasingFar = false;
      state.handlers.onCatchCursor?.();
    }

    if (!errand || errand.kind === "sit") return;
    const point = errandPoint(state, errand);
    if (!point) {
      if (errand.kind === "goTo") errand.resolve?.(false);
      endErrand();
      return;
    }
    const distance = Math.hypot(point.x - state.nekoPosX, point.y - state.nekoPosY);
    // Close enough, or stopped as near as the path allows.
    const arrived = distance < 14 || (state.idleTime > 2 && distance < 64);
    switch (errand.kind) {
      case "goTo":
        if (!errand.arrived && (arrived || (state.idleTime > 2 && ++errand.frames > 30))) {
          errand.arrived = true;
          errand.resolve?.(true);
          errand.resolve = undefined;
        }
        return;
      case "treat":
        if (arrived) {
          if (eatTreat(errand.treat)) {
            const affection = bumpAffection(state);
            speak(deps, TREAT_MESSAGES);
            playSound(deps, "eat");
            state.handlers.onTreat?.({ affection });
          }
          endErrand();
        } else if (++errand.frames > 300 || state.idleTime > 20) {
          // Resting short of the treat means the way is blocked; leave it for another cat.
          unreachable.add(errand.treat);
          endErrand();
        }
        return;
      case "box":
        if (!errand.arrived) {
          if (arrived) {
            errand.arrived = true;
            errand.frames = 0;
            speak(deps, BOX_MESSAGES);
            if (state.cfg.sleepEnabled) {
              state.idleAnimation = "sleeping";
              state.idleAnimationFrame = 0;
            }
          } else if (++errand.frames > 100) endErrand(ERRAND_REST_FRAMES);
        } else if (++errand.frames > BOX_NAP_FRAMES) endErrand(ERRAND_REST_FRAMES);
        return;
      case "knock":
        if (errand.phase === "approach") {
          if (arrived) {
            errand.phase = "stare";
            errand.frames = 0;
            rouse(state);
            speak(deps, KNOCK_STARE_MESSAGES);
          } else if (++errand.frames > 100) endErrand(ERRAND_REST_FRAMES);
          return;
        }
        // Stare at the visitor, then paw the thing off its shelf.
        setSprite(
          deps,
          ++errand.frames >= KNOCK_STARE_FRAMES ? (errand.direction === 1 ? "E" : "W") : "idle",
          errand.frames,
        );
        if (errand.frames >= KNOCK_STARE_FRAMES) {
          knockOver(errand.el, errand.direction);
          speak(deps, KNOCK_MESSAGES);
          playSound(deps, "hiss");
          endErrand(ERRAND_REST_FRAMES);
        }
        return;
    }
  };

  const place = (x: number, y: number) => {
    const state = s();
    state.nekoPosX = x;
    state.nekoPosY = y;
    el.style.left = `${Math.floor(x - TILE / 2)}px`;
    el.style.top = `${Math.floor(y - TILE / 2)}px`;
  };

  const land = (hard: boolean) => {
    const state = s();
    cancelAnimationFrame(flight);
    flight = 0;
    state.grab = { phase: "landed", frames: 8 };
    state.nekoVelX = state.nekoVelY = 0;
    state.currentPath = [];
    clearRotation(deps);
    speak(deps, hard ? TOSS_HARD_MESSAGES : TOSS_SOFT_MESSAGES);
    playSound(deps, hard ? "hiss" : "pet");
  };

  /** Flight runs on animation frames so a toss looks smooth; the cat walks at 10fps. */
  const fly = (vx: number, vy: number, hard: boolean) => {
    let last = performance.now();
    let spin = 0;
    const step = (now: number) => {
      const state = s();
      if (state.grab?.phase !== "flying") return;
      const dt = Math.min(50, now - last);
      last = now;
      if (state.cfg.paused) {
        flight = requestAnimationFrame(step);
        return;
      }
      const from = { x: state.nekoPosX, y: state.nekoPosY };
      let x = from.x + vx * dt;
      let y = from.y + vy * dt;
      const maxX = window.innerWidth - 16;
      const maxY = window.innerHeight - 16;
      if (x < 16 || x > maxX) {
        vx *= -0.5;
        x = Math.max(16, Math.min(maxX, x));
      }
      if (y < 16 || y > maxY) {
        vy *= -0.5;
        y = Math.max(16, Math.min(maxY, y));
      }
      const safe = constrainZoneMovement(from, { x, y }, state.zoneState.blocked);
      if (safe.x !== x || safe.y !== y) vx = vy = 0;
      place(safe.x, safe.y);
      const drag = Math.exp(-dt / 260);
      vx *= drag;
      vy *= drag;
      spin += vx * dt * 0.9;
      el.style.transform = `scale(${state.cfg.scale}) rotate(${spin}deg)`;
      if (Math.hypot(vx, vy) < 0.06) land(hard);
      else flight = requestAnimationFrame(step);
    };
    flight = requestAnimationFrame(step);
  };

  /** Runs instead of walking while the cat is carried, flying, or catching its breath. */
  const tickGrab = (): boolean => {
    const state = s();
    const grab = state.grab;
    if (!grab) return false;
    state.idleAnimation = null;
    state.freerunMode = false;
    if (grab.phase === "landed") {
      setSprite(deps, "idle", 0);
      state.idleTime = Math.max(state.idleTime, 1);
      if (--grab.frames <= 0) state.grab = null;
      return true;
    }
    setSprite(deps, "alert", 0);
    state.idleTime = 0;
    return true;
  };

  const onPointerDown = (event: PointerEvent) => {
    const state = s();
    if (!state.cfg.grabbable || event.button > 0 || state.cfg.paused) return;
    event.preventDefault();
    el.setPointerCapture?.(event.pointerId);
    cancelAnimationFrame(flight);
    rouse(state);
    if (state.errand?.kind === "box" || state.errand?.kind === "knock") endErrand();
    state.grab = {
      phase: "held",
      samples: [{ x: event.clientX, y: event.clientY, t: event.timeStamp }],
      startT: event.timeStamp,
      travel: 0,
    };
    el.style.cursor = "grabbing";
    setSprite(deps, "alert", 0);
    clearRotation(deps);
  };

  const onPointerMove = (event: PointerEvent) => {
    const state = s();
    const grab = state.grab;
    if (grab?.phase !== "held") return;
    const previous = grab.samples.at(-1)!;
    grab.travel += Math.hypot(event.clientX - previous.x, event.clientY - previous.y);
    grab.samples.push({
      x: event.clientX,
      y: event.clientY,
      t: event.timeStamp,
    });
    if (grab.samples.length > 8) grab.samples.shift();
    place(
      Math.max(16, Math.min(window.innerWidth - 16, event.clientX)),
      Math.max(16, Math.min(window.innerHeight - 16, event.clientY)),
    );
    // Let the cat chase from where it was dropped, not from where the pointer was before.
    state.mousePosX = event.clientX;
    state.mousePosY = event.clientY;
    if (grab.travel > 40 && !state.bubbleVisible && Math.random() < 0.02)
      speak(deps, HELD_MESSAGES);
  };

  const onPointerUp = (event: PointerEvent) => {
    const state = s();
    const grab = state.grab;
    if (grab?.phase !== "held") return;
    el.style.cursor = "grab";
    if (grab.travel < 6 && event.timeStamp - grab.startT < 500) {
      state.grab = null;
      petCat(deps);
      return;
    }
    const recent = grab.samples.filter((sample) => event.timeStamp - sample.t < 100);
    const first = recent[0] ?? grab.samples.at(-1)!;
    const elapsed = Math.max(16, event.timeStamp - first.t);
    let vx = (event.clientX - first.x) / elapsed;
    let vy = (event.clientY - first.y) / elapsed;
    const speed = Math.hypot(vx, vy);
    if (speed > MAX_TOSS_SPEED) {
      vx = (vx / speed) * MAX_TOSS_SPEED;
      vy = (vy / speed) * MAX_TOSS_SPEED;
    }
    if (speed < 0.25) {
      land(false);
      return;
    }
    const hard = speed > HARD_TOSS_SPEED;
    state.grab = { phase: "flying", vx, vy, spin: 0, hard };
    state.handlers.onToss?.({
      speed: Math.round(Math.min(speed, MAX_TOSS_SPEED) * 1000),
    });
    fly(vx, vy, hard);
  };

  const onPointerCancel = () => {
    if (s().grab?.phase === "held") land(false);
  };

  const onDoubleClick = (event: MouseEvent) => {
    const state = s();
    if (!state.cfg.treats || handledEvents.has(event)) return;
    if (event.target instanceof Element && event.target.closest(TYPING_TARGETS)) return;
    // Double-clicking text selects a word; leave reading alone.
    if (window.getSelection()?.toString().trim() || isOverText(event.clientX, event.clientY))
      return;
    const point = { x: event.clientX, y: event.clientY };
    if (state.zoneState.blocked.some((rect) => containsPoint(rect, point))) return;
    handledEvents.add(event);
    dropTreat(point.x, point.y, state.zIndex);
  };

  const requestSay = (target: Element) => {
    const state = s();
    const text = target.getAttribute("data-oneko-say")?.trim();
    if (!text || !state.cfg.bubbleEnabled || state.cfg.paused) return;
    const rect = target.getBoundingClientRect();
    if (
      !isNearestCat(state, {
        x: rect.left + rect.width / 2,
        y: rect.top + rect.height / 2,
      })
    )
      return;
    state.sayRequest = {
      text: text.slice(0, 200),
      frames: state.cfg.bubbleDisplayFrames,
    };
  };

  const onMouseOver = (event: MouseEvent) => {
    const target =
      event.target instanceof Element ? event.target.closest("[data-oneko-say]") : null;
    if (target === sayTarget) return;
    sayTarget = target;
    clearTimeout(sayTimer);
    if (target) sayTimer = setTimeout(() => requestSay(target), 350);
  };

  const onFocusIn = (event: FocusEvent) => {
    const target =
      event.target instanceof Element ? event.target.closest("[data-oneko-say]") : null;
    if (target) requestSay(target);
  };

  syncGrabbable();
  el.addEventListener("pointerdown", onPointerDown);
  el.addEventListener("pointermove", onPointerMove);
  el.addEventListener("pointerup", onPointerUp);
  el.addEventListener("pointercancel", onPointerCancel);
  document.addEventListener("dblclick", onDoubleClick);
  document.addEventListener("mouseover", onMouseOver);
  document.addEventListener("focusin", onFocusIn);

  const dispose = () => {
    const state = s();
    cancelAnimationFrame(flight);
    clearTimeout(sayTimer);
    el.removeEventListener("pointerdown", onPointerDown);
    el.removeEventListener("pointermove", onPointerMove);
    el.removeEventListener("pointerup", onPointerUp);
    el.removeEventListener("pointercancel", onPointerCancel);
    document.removeEventListener("dblclick", onDoubleClick);
    document.removeEventListener("mouseover", onMouseOver);
    document.removeEventListener("focusin", onFocusIn);
    if (state.cfg.affection && state.affectionLoaded)
      writeAffection(state.affectionKey, state.affection);
    // A remount starts fresh; requests made through the API are told they will not finish.
    if (state.errand?.kind === "goTo") state.errand.resolve?.(false);
    state.errand = null;
    state.grab = null;
    state.season = null;
    deps.hat?.remove();
    deps.hat = undefined;
  };

  return { upkeep, tickGrab, tickErrand, dispose };
}

export type CatPlay = ReturnType<typeof createPlay>;

import { defaultSpriteSets, DIRECTION_RANGES, TILE } from "../constants";
import { hatOffset } from "../seasons";
import type { CatAnimationDeps } from "./deps";

export function setSprite(
  deps: CatAnimationDeps,
  name: keyof typeof defaultSpriteSets | string,
  frame: number,
) {
  const sprites = defaultSpriteSets[name as keyof typeof defaultSpriteSets];
  if (!sprites?.length) {
    return;
  }
  const sprite = sprites[frame % sprites.length];
  deps.el.style.backgroundPosition = `${sprite[0] * TILE}px ${sprite[1] * TILE}px`;
  if (deps.hat) {
    const offset = hatOffset(sprite[0], sprite[1]);
    deps.hat.style.display = offset ? "" : "none";
    if (offset) deps.hat.style.transform = `translate(${offset.left}px, ${offset.top}px)`;
  }
}

function getDirectionFromAngle(angle: number): string {
  if (angle >= 157.5 || angle < -157.5) {
    return "W";
  }
  for (const range of DIRECTION_RANGES) {
    if (angle >= range.min && angle < range.max) {
      return range.dir;
    }
  }
  return "E";
}

export function directionFromDelta(dx: number, dy: number) {
  if (Math.abs(dx) < 1 && Math.abs(dy) < 1) {
    return null;
  }
  return getDirectionFromAngle(Math.atan2(dy, dx) * (180 / Math.PI));
}

export function clearRotation(deps: CatAnimationDeps) {
  const s = deps.stateRef.current;
  if (s.currentRotation !== 0) {
    s.currentRotation = 0;
    deps.el.style.transform = `scale(${s.cfg.scale}) rotate(0deg)`;
  }
}

import { dropTreat } from "./treats";
import type { CatRuntimeState } from "./types";

/** Imperative controls for a running cat, for tours, games, and onboarding. */
export interface OnekoControls {
  /**
   * Walk to an element (or a CSS selector, or a viewport point) and stay there until follow() or
   * another request. Resolves true on arrival, false if the cat is sent elsewhere first or the
   * target disappears.
   */
  goTo(target: Element | string | { x: number; y: number }): Promise<boolean>;
  /** Show a bubble now, even when automatic bubbles are off. Duration defaults to bubbleDisplayFrames. */
  say(text: string, options?: { duration?: number }): void;
  /** Sit where the cat is until follow(). */
  sit(): void;
  /** Go back to chasing the cursor after goTo() or sit(). */
  follow(): void;
  /** Pet the cat, as if a visitor did. */
  pet(): void;
  /** Drop a treat at a viewport point, or at the cursor. Works without the treats option. */
  dropTreat(x?: number, y?: number): void;
}

export function createCatControls(stateRef: { current: CatRuntimeState }): OnekoControls {
  const s = () => stateRef.current;
  const release = () => {
    const errand = s().errand;
    if (errand?.kind === "goTo") errand.resolve?.(false);
    s().errand = null;
  };
  return {
    goTo(target) {
      const resolved = resolveTarget(target);
      release();
      if (!resolved) return Promise.resolve(false);
      return new Promise((resolve) => {
        const state = s();
        state.errand = {
          kind: "goTo",
          target: resolved,
          frames: 0,
          arrived: false,
          resolve,
        };
        state.typingNap = false;
      });
    },
    say(text, options = {}) {
      const state = s();
      const frames = Number.isFinite(options.duration)
        ? Math.max(1, Math.round(options.duration! / 100))
        : state.cfg.bubbleDisplayFrames;
      state.sayRequest = { text: String(text).slice(0, 280), frames };
    },
    sit() {
      release();
      s().errand = { kind: "sit" };
    },
    follow: release,
    pet() {
      s().petRequest = true;
    },
    dropTreat(x, y) {
      const state = s();
      dropTreat(x ?? state.mousePosX, y ?? state.mousePosY, state.zIndex);
    },
  };
}

/** An element, or a finite point. Invalid selectors and NaN coordinates find nothing. */
function resolveTarget(
  target: Parameters<OnekoControls["goTo"]>[0],
): Element | { x: number; y: number } | null {
  if (typeof target === "string") {
    try {
      return document.querySelector(target);
    } catch {
      return null;
    }
  }
  if ("nodeType" in target) return target;
  return Number.isFinite(target.x) && Number.isFinite(target.y) ? target : null;
}

import { debugColor } from "../constants";
import type { CatRuntimeState } from "../types";
import { makeBtn, makeRow, sectionLabel } from "./ui";

export function appendBubbleSection(
  body: HTMLElement,
  stateRef: { current: CatRuntimeState },
  bubbleEl: HTMLDivElement,
  bubbleTextEl: HTMLDivElement,
  showBubble: () => void,
  hideBubble: () => void,
  bubbleDisplayFrames: number,
) {
  body.appendChild(sectionLabel("bubble"));

  const showBubbleBtn = makeBtn("show", () => showBubble());
  const hideBubbleBtn = makeBtn("hide", () => hideBubble());
  body.appendChild(makeRow(showBubbleBtn, hideBubbleBtn));

  const bubbleInput = document.createElement("input");
  bubbleInput.type = "text";
  bubbleInput.placeholder = "custom text...";
  bubbleInput.style.cssText = [
    `background:${debugColor.controlBg}`,
    `border:1px solid ${debugColor.controlBorder}`,
    `color:${debugColor.panelText}`,
    "border-radius:4px",
    "padding:2px 6px",
    "font-family:inherit",
    "font-size:11px",
    "flex:1",
    "min-width:0",
  ].join(";");

  const setTextBtn = makeBtn("set", () => {
    if (bubbleInput.value.trim()) {
      bubbleTextEl.textContent = bubbleInput.value.trim();
      stateRef.current.bubbleVisible = true;
      stateRef.current.bubbleTimer = bubbleDisplayFrames;
      bubbleEl.style.opacity = "1";
    }
  });

  body.appendChild(makeRow(bubbleInput, setTextBtn));
}

import { debugColor } from "../constants";
import type { CatActivityState, CatRuntimeState, IdleActivityState } from "../types";
import { makeBtn, makeRow, sectionLabel, selectStyle } from "./ui";

const ALL_STATES = [
  "moving",
  "idle",
  "sleeping",
  "scratchSelf",
  "tired",
  "alert",
  "scratchWallN",
  "scratchWallS",
  "scratchWallE",
  "scratchWallW",
  "freerun",
] as const;

function applyForcedState(s: CatRuntimeState, chosen: CatActivityState, locked: boolean) {
  s.idleAnimation = null;
  s.idleAnimationFrame = 0;
  s.freerunMode = false;
  s.freerunTimer = 0;

  if (chosen === "moving") {
    s.idleTime = 0;
    s.stateLocked = locked;
    return;
  }

  if (chosen === "idle") {
    s.idleTime = 200;
    s.stateLocked = locked;
    return;
  }

  if (chosen === "freerun") {
    s.freerunMode = true;
    s.freerunTimer = 600;
    s.stateLocked = locked;
    return;
  }

  s.idleTime = 200;
  s.idleAnimation = chosen as IdleActivityState;
  s.idleAnimationFrame = 0;
  s.stateLocked = locked;
}

export function appendForceStateSection(body: HTMLElement, stateRef: { current: CatRuntimeState }) {
  body.appendChild(sectionLabel("force state"));

  const stateSelect = document.createElement("select");
  stateSelect.style.cssText = selectStyle;
  for (const name of ALL_STATES) {
    const opt = document.createElement("option");
    opt.value = name;
    opt.textContent = name;
    stateSelect.appendChild(opt);
  }

  const lockChk = document.createElement("input");
  lockChk.type = "checkbox";
  lockChk.title = "lock state (prevent auto-reset)";
  lockChk.style.cssText = `cursor:pointer;accent-color:${debugColor.accent};`;
  lockChk.addEventListener("change", () => {
    stateRef.current.stateLocked = lockChk.checked;
  });

  const lockLbl = document.createElement("label");
  lockLbl.title = "lock state";
  lockLbl.style.cssText = `display:flex;align-items:center;gap:3px;cursor:pointer;font-size:10px;color:${debugColor.accent};white-space:nowrap;`;
  lockLbl.appendChild(lockChk);
  lockLbl.append("lock");

  body.appendChild(makeRow(stateSelect));

  const forceStateBtn = makeBtn("apply", () => {
    applyForcedState(stateRef.current, stateSelect.value as CatActivityState, lockChk.checked);
  });

  body.appendChild(makeRow(forceStateBtn, lockLbl));
}

import { debugColor } from "../constants";
import type { CatRuntimeState } from "../types";
import { appendBubbleSection } from "./bubble";
import { appendForceStateSection } from "./force-state";
import { appendPlaybackSection } from "./playback";
import { appendPositionSection } from "./position";
import { appendSpeedSection } from "./speed";
import { BASE_STYLE } from "./ui";

export interface DebugControlsParams {
  stateRef: { current: CatRuntimeState };
  el: HTMLDivElement;
  bubbleEl: HTMLDivElement;
  bubbleTextEl: HTMLDivElement;
  frame: () => void;
  showBubble: () => void;
  hideBubble: () => void;
  bubbleDisplayFrames: number;
}

export function createDebugControls({
  stateRef,
  el,
  bubbleEl,
  bubbleTextEl,
  frame,
  showBubble,
  hideBubble,
  bubbleDisplayFrames,
}: DebugControlsParams): HTMLDivElement {
  const panel = document.createElement("div");
  panel.setAttribute("aria-hidden", "true");
  panel.style.cssText = "user-select:none;pointer-events:auto;";

  const header = document.createElement("div");
  header.style.cssText = `${BASE_STYLE};padding:6px 14px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;`;

  const headerTitle = document.createElement("span");
  headerTitle.textContent = "controls";
  headerTitle.style.cssText = `font-weight:bold;font-size:10px;letter-spacing:0.05em;text-transform:uppercase;color:${debugColor.panelSubtle};`;

  const chevron = document.createElement("span");
  chevron.textContent = "▾";
  chevron.style.cssText = `font-size:10px;color:${debugColor.panelSubtle};`;

  header.appendChild(headerTitle);
  header.appendChild(chevron);
  panel.appendChild(header);

  const body = document.createElement("div");
  body.style.cssText = `${BASE_STYLE};padding:6px 14px 10px;margin-top:4px;`;
  panel.appendChild(body);

  let collapsed = false;
  header.addEventListener("click", () => {
    collapsed = !collapsed;
    body.style.display = collapsed ? "none" : "block";
    chevron.textContent = collapsed ? "▸" : "▾";
  });

  appendPlaybackSection(body, stateRef, frame);
  appendForceStateSection(body, stateRef);
  appendBubbleSection(
    body,
    stateRef,
    bubbleEl,
    bubbleTextEl,
    showBubble,
    hideBubble,
    bubbleDisplayFrames,
  );
  appendPositionSection(body, stateRef, el);
  appendSpeedSection(body, stateRef);

  return panel;
}

