export function createKonamiHandler(
  stateRef: { current: CatRuntimeState },
  debugSVG: SVGSVGElement,
  debugWrapper: HTMLDivElement,
): (e: KeyboardEvent) => void {
  const konamiBuffer: string[] = [];

  return (e: KeyboardEvent) => {
    konamiBuffer.push(e.code);
    if (konamiBuffer.length > KONAMI_SEQUENCE.length) {
      konamiBuffer.shift();
    }
    if (konamiBuffer.join(",") !== KONAMI_TARGET) {
      return;
    }

    stateRef.current.debugMode = !stateRef.current.debugMode;
    if (stateRef.current.debugMode) {
      debugSVG.style.display = "block";
      debugWrapper.style.display = "flex";
      return;
    }

    debugSVG.style.display = "none";
    debugWrapper.style.display = "none";
    stateRef.current.paused = false;
    stateRef.current.stateLocked = false;
    stateRef.current.noFollow = false;
  };
}

const DOT_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 7 7" shape-rendering="crispEdges" aria-hidden="true" focusable="false" style="display:block;width:100%;height:100%"><rect x="3" y="0" width="1" height="1" fill="var(--destructive)"/><rect x="2" y="1" width="3" height="1" fill="var(--destructive)"/><rect x="1" y="2" width="5" height="1" fill="var(--destructive)"/><rect x="0" y="3" width="7" height="1" fill="var(--destructive)"/><rect x="1" y="4" width="5" height="1" fill="var(--destructive)"/><rect x="2" y="5" width="3" height="1" fill="var(--destructive)"/><rect x="3" y="6" width="1" height="1" fill="var(--destructive)"/><rect x="2" y="2" width="1" height="1" fill="var(--accent)"/></svg>`;

const LASER_SVG = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 22 5" shape-rendering="crispEdges" aria-hidden="true" focusable="false" style="display:block;width:100%;height:100%"><rect x="2" y="0" width="16" height="1" fill="var(--destructive)"/><rect x="1" y="1" width="18" height="1" fill="var(--destructive)"/><rect x="0" y="2" width="20" height="1" fill="var(--destructive)"/><rect x="1" y="3" width="18" height="1" fill="var(--destructive)"/><rect x="2" y="4" width="16" height="1" fill="var(--destructive)"/><rect x="11" y="1" width="1" height="1" fill="var(--primary-foreground)"/><rect x="13" y="1" width="1" height="1" fill="var(--primary-foreground)"/><rect x="15" y="1" width="1" height="1" fill="var(--primary-foreground)"/><rect x="11" y="2" width="1" height="1" fill="var(--primary-foreground)"/><rect x="13" y="2" width="1" height="1" fill="var(--primary-foreground)"/><rect x="15" y="2" width="1" height="1" fill="var(--primary-foreground)"/><rect x="11" y="3" width="1" height="1" fill="var(--primary-foreground)"/><rect x="13" y="3" width="1" height="1" fill="var(--primary-foreground)"/><rect x="15" y="3" width="1" height="1" fill="var(--primary-foreground)"/><rect x="4" y="0" width="3" height="1" fill="var(--primary)"/><rect x="4" y="1" width="3" height="1" fill="var(--primary)"/><rect x="18" y="1" width="3" height="1" fill="var(--accent)"/><rect x="18" y="2" width="3" height="1" fill="var(--accent)"/><rect x="18" y="3" width="3" height="1" fill="var(--accent)"/></svg>`;

const DOT_SIZE = 9;
const LASER_W = 88;
const LASER_H = 20;
const ANCHOR_INSET = 10;
const TRAIL_LEN = 22;

function makeDot(zIndex: number, size: number, opacity: number, glow: boolean) {
  const d = document.createElement("div");
  d.setAttribute("aria-hidden", "true");
  d.style.cssText = [
    "position:fixed",
    `width:${size}px`,
    `height:${size}px`,
    "pointer-events:none",
    `z-index:${zIndex}`,
    "left:0",
    "top:0",
    "image-rendering:pixelated",
    `opacity:${opacity}`,
    "transform:translate(-50%,-50%) translate(-100px,-100px)",
    "will-change:transform",
    glow
      ? "filter:drop-shadow(0 0 4px var(--destructive)) drop-shadow(0 0 12px color-mix(in srgb, var(--destructive) 55%, transparent))"
      : "",
  ].join(";");
  d.innerHTML = DOT_SVG;
  return d;
}

function createTrail(zIndex: number) {
  const trail: HTMLDivElement[] = [];
  for (let i = 1; i <= TRAIL_LEN; i++) {
    const t = i / (TRAIL_LEN + 1);
    const size = Math.max(2, DOT_SIZE * (1 - t * 0.85));
    const opacity = 0.55 * (1 - t);
    trail.push(makeDot(zIndex, size, opacity, false));
  }
  return trail;
}

function createLaserBody(zIndex: number) {
  const laser = document.createElement("div");
  laser.setAttribute("aria-hidden", "true");
  laser.style.cssText = [
    "position:fixed",
    `width:${LASER_W}px`,
    `height:${LASER_H}px`,
    "pointer-events:none",
    `z-index:${zIndex}`,
    "left:0",
    "top:0",
    "image-rendering:pixelated",
    "transform-origin:100% 50%",
    "filter:drop-shadow(0 0 6px color-mix(in srgb, var(--destructive) 45%, transparent))",
    "will-change:transform",
  ].join(";");
  laser.innerHTML = LASER_SVG;
  return laser;
}

export function mountLaserCursor(zIndex: number): () => void {
  const dot = makeDot(zIndex, DOT_SIZE, 1, true);
  const trail = createTrail(zIndex);
  const laser = createLaserBody(zIndex);

  document.body.appendChild(laser);
  for (const t of trail) {
    document.body.appendChild(t);
  }
  document.body.appendChild(dot);
  const previousCursor = document.body.style.getPropertyValue("cursor");
  const previousPriority = document.body.style.getPropertyPriority("cursor");
  document.body.style.setProperty("cursor", "none");

  let pointerX = window.innerWidth / 2;
  let pointerY = window.innerHeight / 2;

  // Ring buffer of recent pointer positions; slot `head` is the newest.
  const SLOTS = TRAIL_LEN + 1;
  const historyX = new Float64Array(SLOTS).fill(pointerX);
  const historyY = new Float64Array(SLOTS).fill(pointerY);
  let head = 0;

  const positionLaser = () => {
    const anchorX = ANCHOR_INSET + LASER_W;
    const anchorY = ANCHOR_INSET + LASER_H / 2;
    const dx = pointerX - anchorX;
    const dy = pointerY - anchorY;
    const angle = (Math.atan2(dy, dx) * 180) / Math.PI + 180;
    laser.style.transform = `translate(${ANCHOR_INSET}px, ${ANCHOR_INSET}px) rotate(${angle}deg)`;
  };

  let rafId = 0;
  /** Frames since the pointer last moved; once the trail has caught up, the loop sleeps. */
  let stillFrames = 0;
  const place = (el: HTMLDivElement, slot: number) => {
    el.style.transform = `translate(-50%,-50%) translate(${historyX[slot]}px, ${historyY[slot]}px)`;
  };
  const tick = () => {
    head = (head + SLOTS - 1) % SLOTS;
    historyX[head] = pointerX;
    historyY[head] = pointerY;
    place(dot, head);
    for (let i = 0; i < trail.length; i++) place(trail[i], (head + i + 1) % SLOTS);
    stillFrames++;
    rafId = stillFrames > SLOTS ? 0 : window.requestAnimationFrame(tick);
  };
  const wake = () => {
    stillFrames = 0;
    if (!rafId) rafId = window.requestAnimationFrame(tick);
  };

  const onMove = (e: MouseEvent) => {
    pointerX = e.clientX;
    pointerY = e.clientY;
    positionLaser();
    wake();
  };

  positionLaser();
  rafId = window.requestAnimationFrame(tick);

  document.addEventListener("mousemove", onMove);
  window.addEventListener("resize", positionLaser);
  window.addEventListener("scroll", positionLaser, { passive: true });

  return () => {
    window.cancelAnimationFrame(rafId);
    document.removeEventListener("mousemove", onMove);
    window.removeEventListener("resize", positionLaser);
    window.removeEventListener("scroll", positionLaser);
    if (dot.parentNode) {
      dot.parentNode.removeChild(dot);
    }
    for (const t of trail) {
      if (t.parentNode) {
        t.parentNode.removeChild(t);
      }
    }
    if (laser.parentNode) {
      laser.parentNode.removeChild(laser);
    }
    if (previousCursor) {
      document.body.style.setProperty("cursor", previousCursor, previousPriority);
    } else {
      document.body.style.removeProperty("cursor");
    }
  };
}

import type { Mood } from "./animation/play-types";

export const NEUTRAL_MOOD: Mood = { speed: 1, freerun: 1, idle: 1 };

/**
 * How a cat feels at a local hour. Cats are crepuscular: most playful at dawn and dusk, drowsy
 * in the early afternoon, and asleep in the small hours. idle scales the rest time before naps.
 */
export function moodForHour(hour: number): Mood {
  if (hour >= 5 && hour < 8) return { speed: 1.25, freerun: 2.5, idle: 1.5 };
  if (hour >= 8 && hour < 12) return { speed: 1.1, freerun: 1.4, idle: 1 };
  if (hour >= 12 && hour < 17) return { speed: 0.9, freerun: 0.7, idle: 0.6 };
  if (hour >= 17 && hour < 21) return { speed: 1.25, freerun: 2.5, idle: 1.5 };
  if (hour >= 21 && hour < 23) return { speed: 1, freerun: 0.8, idle: 0.8 };
  return { speed: 0.7, freerun: 0.25, idle: 0.35 };
}

import { MIN_OBSTACLE_AREA } from "./constants";

type RectLike = {
  left: number;
  top: number;
  right: number;
  bottom: number;
  width: number;
  height: number;
};

export function shouldIncludeObstacleRect(
  rect: RectLike,
  viewportWidth: number,
  viewportHeight: number,
): boolean {
  if (rect.width * rect.height < MIN_OBSTACLE_AREA) {
    return false;
  }
  if (rect.right < 0 || rect.bottom < 0 || rect.left > viewportWidth || rect.top > viewportHeight) {
    return false;
  }
  if (rect.width > viewportWidth * 0.85 && rect.height > viewportHeight * 0.5) {
    return false;
  }
  return true;
}

/** Allowed values for the string options. Types, validators, and framework props derive from these. */
export const BUBBLE_PLACEMENTS = ["auto", "above", "below"] as const;
export const REDUCED_MOTION_MODES = ["hide", "rest"] as const;
export const CHASE_TARGETS = ["cursor", "cat"] as const;

export function isOneOf<T extends string>(values: readonly T[], value: unknown): value is T {
  return typeof value === "string" && (values as readonly string[]).includes(value);
}

import { TILE } from "./constants";
import type { CatRuntimeState, PathPoint } from "./types";

/** Every running cat on the page, in mount order. A cat with chase="cat" follows the one before it. */
const pack: CatRuntimeState[] = [];
// Restarting a cat (for example after a zIndex change) keeps its first place in line.
const firstSeen = new WeakMap<CatRuntimeState, number>();
let arrivals = 0;

export function joinPack(state: CatRuntimeState): () => void {
  if (!firstSeen.has(state)) firstSeen.set(state, arrivals++);
  if (!pack.includes(state)) {
    pack.push(state);
    pack.sort((a, b) => firstSeen.get(a)! - firstSeen.get(b)!);
  }
  return () => {
    const index = pack.indexOf(state);
    if (index !== -1) pack.splice(index, 1);
    for (const cat of pack) cat.leaderTarget = null;
  };
}

/** Where the cat ahead of this one is, or null when it leads (or chases the cursor). */
export function leaderPosition(state: CatRuntimeState): PathPoint | null {
  if (state.cfg.chase !== "cat") return null;
  const leader = pack[pack.indexOf(state) - 1];
  return leader ? { x: leader.nekoPosX, y: leader.nekoPosY } : null;
}

/** True when no other running cat is closer to a point, so only one cat answers a page event. */
export function isNearestCat(state: CatRuntimeState, point: PathPoint): boolean {
  const distance = (cat: CatRuntimeState) =>
    Math.hypot(cat.nekoPosX - point.x, cat.nekoPosY - point.y);
  const mine = distance(state);
  const order = pack.indexOf(state);
  return pack.every(
    (cat, index) =>
      cat === state || distance(cat) > mine || (distance(cat) === mine && index > order),
  );
}

export function packSize(): number {
  return pack.length;
}

/** True when another cat is asleep close enough to curl up next to. */
export function napmateNearby(state: CatRuntimeState): boolean {
  const reach = TILE * Math.max(1, state.cfg.scale) * 2;
  return pack.some(
    (cat) =>
      cat !== state &&
      cat.idleAnimation === "sleeping" &&
      Math.hypot(cat.nekoPosX - state.nekoPosX, cat.nekoPosY - state.nekoPosY) < reach,
  );
}

/** Visitor preference, shared by every cat on the site and remembered across visits. */
export const HIDDEN_STORAGE_KEY = "oneko:hidden";
const HIDDEN_EVENT = "oneko:hiddenchange";
let hiddenWithoutStorage = false;

export function areCatsHidden(): boolean {
  try {
    return localStorage.getItem(HIDDEN_STORAGE_KEY) === "1";
  } catch {
    return hiddenWithoutStorage;
  }
}

export function setCatsHidden(hidden: boolean): void {
  hiddenWithoutStorage = hidden;
  try {
    if (hidden) localStorage.setItem(HIDDEN_STORAGE_KEY, "1");
    else localStorage.removeItem(HIDDEN_STORAGE_KEY);
  } catch {
    /* Storage can be unavailable; the event still updates this page. */
  }
  window.dispatchEvent(new CustomEvent(HIDDEN_EVENT, { detail: { hidden } }));
}

/** Calls back when cats are hidden or shown, in this tab or another one. */
export function onCatsHiddenChange(callback: () => void): () => void {
  const onStorage = (event: StorageEvent) => {
    if (event.key === HIDDEN_STORAGE_KEY || event.key === null) callback();
  };
  window.addEventListener(HIDDEN_EVENT, callback);
  window.addEventListener("storage", onStorage);
  return () => {
    window.removeEventListener(HIDDEN_EVENT, callback);
    window.removeEventListener("storage", onStorage);
  };
}

import { CELL_SIZE, NEIGHBOR_OFFSETS, OBSTACLE_SELECTOR, SPRITE_RADIUS } from "./constants";
import { shouldIncludeObstacleRect } from "./obstacle-filters";
import type { ObstacleRect, PathPoint } from "./types";

// Flat index of the neighbor at (r+dr, c+dc), or -1 if it falls outside the grid.
function neighborIndex(
  r: number,
  c: number,
  dr: number,
  dc: number,
  rows: number,
  cols: number,
): number {
  const nr = r + dr;
  const nc = c + dc;
  if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) return -1;
  return nr * cols + nc;
}

export function collectObstacles(): ObstacleRect[] {
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const rects: ObstacleRect[] = [];

  for (const node of document.querySelectorAll(OBSTACLE_SELECTOR)) {
    // Favorite spots and boxes are places to go, not things to walk around.
    if (node.closest('[data-oneko-zone="attract"],[data-oneko-box]')) continue;
    const r = node.getBoundingClientRect();
    if (shouldIncludeObstacleRect(r, vw, vh)) {
      rects.push({ left: r.left, top: r.top, right: r.right, bottom: r.bottom });
    }
  }

  return rects;
}

export function buildGrid(rects: ObstacleRect[], cols: number, rows: number): Uint8Array {
  const grid = new Uint8Array(cols * rows);

  for (const rect of rects) {
    const c0 = Math.max(0, Math.floor((rect.left - SPRITE_RADIUS) / CELL_SIZE));
    const c1 = Math.min(cols - 1, Math.ceil((rect.right + SPRITE_RADIUS) / CELL_SIZE));
    const r0 = Math.max(0, Math.floor((rect.top - SPRITE_RADIUS) / CELL_SIZE));
    const r1 = Math.min(rows - 1, Math.ceil((rect.bottom + SPRITE_RADIUS) / CELL_SIZE));

    for (let row = r0; row <= r1; row++) {
      for (let col = c0; col <= c1; col++) {
        grid[row * cols + col] = 1;
      }
    }
  }

  return grid;
}

export function worldToCell(worldX: number, worldY: number, cols: number, rows: number): number {
  const col = Math.max(0, Math.min(cols - 1, Math.floor(worldX / CELL_SIZE)));
  const row = Math.max(0, Math.min(rows - 1, Math.floor(worldY / CELL_SIZE)));
  return row * cols + col;
}

function cellToWorld(idx: number, cols: number): PathPoint {
  return {
    x: ((idx % cols) + 0.5) * CELL_SIZE,
    y: (Math.floor(idx / cols) + 0.5) * CELL_SIZE,
  };
}

export function nearestWalkable(
  startIdx: number,
  grid: Uint8Array,
  cols: number,
  rows: number,
): number {
  if (grid[startIdx] === 0) {
    return startIdx;
  }

  const visited = new Uint8Array(grid.length);
  const queue: number[] = [startIdx];
  visited[startIdx] = 1;
  let head = 0;

  while (head < queue.length) {
    const idx = queue[head++];
    const r = Math.floor(idx / cols);
    const c = idx % cols;

    for (const [dr, dc] of NEIGHBOR_OFFSETS) {
      const nIdx = neighborIndex(r, c, dr, dc, rows, cols);
      if (nIdx === -1 || visited[nIdx]) {
        continue;
      }
      visited[nIdx] = 1;
      if (grid[nIdx] === 0) {
        return nIdx;
      }
      queue.push(nIdx);
    }
  }

  return startIdx;
}

function heapBubble(data: [number, number][], i: number): void {
  let idx = i;
  while (idx > 0) {
    const parent = Math.floor((idx - 1) / 2);
    if (data[parent][0] <= data[idx][0]) {
      break;
    }
    const tmp = data[parent];
    data[parent] = data[idx];
    data[idx] = tmp;
    idx = parent;
  }
}

function heapSink(data: [number, number][], i: number): void {
  const n = data.length;
  let idx = i;

  for (let step = 0; step < n; step++) {
    let smallest = idx;
    const left = 2 * idx + 1;
    const right = 2 * idx + 2;
    if (left < n && data[left][0] < data[smallest][0]) {
      smallest = left;
    }
    if (right < n && data[right][0] < data[smallest][0]) {
      smallest = right;
    }
    if (smallest === idx) {
      break;
    }
    const tmp = data[smallest];
    data[smallest] = data[idx];
    data[idx] = tmp;
    idx = smallest;
  }
}

function smoothPath(rawPath: number[], cols: number): PathPoint[] {
  const points = rawPath.map((idx) => cellToWorld(idx, cols));
  if (points.length <= 2) {
    return points;
  }

  const result: PathPoint[] = [points[0]];

  for (let i = 1; i < points.length - 1; i++) {
    const prev = result.at(-1) as PathPoint;
    const cur = points[i];
    const next = points[i + 1];
    const cross = (cur.x - prev.x) * (next.y - cur.y) - (cur.y - prev.y) * (next.x - cur.x);
    if (Math.abs(cross) > 1e-6) {
      result.push(cur);
    }
  }

  result.push(points.at(-1) as PathPoint);
  return result;
}

function relaxNeighbors(
  idx: number,
  cols: number,
  rows: number,
  grid: Uint8Array,
  dist: Float64Array,
  prev: Int32Array,
  heap: [number, number][],
) {
  const r = Math.floor(idx / cols);
  const c = idx % cols;

  for (const [dr, dc, edgeCost] of NEIGHBOR_OFFSETS) {
    const nIdx = neighborIndex(r, c, dr, dc, rows, cols);
    if (nIdx === -1 || grid[nIdx] === 1) {
      continue;
    }
    if (dr !== 0 && dc !== 0 && (grid[r * cols + c + dc] || grid[(r + dr) * cols + c])) continue;
    const newDist = dist[idx] + edgeCost;
    if (newDist < dist[nIdx]) {
      dist[nIdx] = newDist;
      prev[nIdx] = idx;
      heap.push([newDist, nIdx]);
      heapBubble(heap, heap.length - 1);
    }
  }
}

function searchRoute(
  startIdx: number,
  goalIdx: number,
  grid: Uint8Array,
  cols: number,
  rows: number,
): Int32Array | null {
  const dist = new Float64Array(grid.length).fill(Number.POSITIVE_INFINITY);
  const prev = new Int32Array(grid.length).fill(-1);
  const heap: [number, number][] = [];

  dist[startIdx] = 0;
  heap.push([0, startIdx]);

  while (heap.length > 0) {
    const top = heap.at(0) as [number, number];
    const last = heap.at(-1) as [number, number];
    heap[0] = last;
    heap.pop();
    heapSink(heap, 0);

    const [cost, idx] = top;
    if (idx === goalIdx) {
      break;
    }
    if (cost > dist[idx]) {
      continue;
    }

    relaxNeighbors(idx, cols, rows, grid, dist, prev, heap);
  }

  return Number.isFinite(dist[goalIdx]) ? prev : null;
}

function reconstructCellPath(prev: Int32Array, goalIdx: number): number[] {
  const rawPath: number[] = [];
  let cur = goalIdx;
  while (cur !== -1) {
    rawPath.push(cur);
    cur = prev[cur];
  }
  rawPath.reverse();
  return rawPath;
}

export function findRoute(
  startIdx: number,
  goalIdx: number,
  grid: Uint8Array,
  cols: number,
  rows: number,
): PathPoint[] {
  if (startIdx === goalIdx) {
    return [cellToWorld(startIdx, cols)];
  }

  const prev = searchRoute(startIdx, goalIdx, grid, cols, rows);
  if (!prev) {
    return [];
  }

  return smoothPath(reconstructCellPath(prev, goalIdx), cols);
}

import { TILE } from "./constants";
import { ONEKO_DEFAULTS } from "./defaults";
import type { CatRuntimeState } from "./types";

export type PersistedPosition = { version: 1; x: number; y: number };

export function parsePersistedPosition(value: unknown): PersistedPosition | null {
  if (!value || typeof value !== "object" || Array.isArray(value)) return null;
  const record = value as Record<string, unknown>;
  if (record.version !== undefined && record.version !== 1) return null;
  const x = record.version === 1 ? record.x : record.nekoPosX;
  const y = record.version === 1 ? record.y : record.nekoPosY;
  if (typeof x !== "number" || !Number.isFinite(x)) return null;
  if (typeof y !== "number" || !Number.isFinite(y)) return null;
  return { version: 1, x, y };
}

/** Saved position clamped to the viewport, or null when absent or invalid. */
export function readPersistedPosition(
  storageKey = ONEKO_DEFAULTS.storageKey,
): { x: number; y: number } | null {
  let position: PersistedPosition | null;
  try {
    position = parsePersistedPosition(
      JSON.parse(window.localStorage.getItem(storageKey) ?? "null"),
    );
  } catch {
    return null;
  }
  if (!position) return null;
  const clamp = (value: number, extent: number) => {
    const inset = Math.min(TILE / 2, Math.max(0, extent / 2));
    return Math.max(inset, Math.min(Math.max(inset, extent - inset), value));
  };
  return {
    x: clamp(position.x, window.innerWidth),
    y: clamp(position.y, window.innerHeight),
  };
}

export function loadPersistedCatState(
  stateRef: { current: CatRuntimeState },
  el: HTMLDivElement,
  storageKey = ONEKO_DEFAULTS.storageKey,
): void {
  const position = readPersistedPosition(storageKey);
  if (!position) return;

  const state = stateRef.current;
  state.nekoPosX = state.mousePosX = position.x;
  state.nekoPosY = state.mousePosY = position.y;
  state.nekoVelX = state.nekoVelY = 0;
  state.currentPath = [];
  state.pathWaypointIdx = 0;
  el.style.left = `${state.nekoPosX - TILE / 2}px`;
  el.style.top = `${state.nekoPosY - TILE / 2}px`;
}

export function createPersistHandler(
  stateRef: { current: CatRuntimeState },
  storageKey = ONEKO_DEFAULTS.storageKey,
): () => void {
  return () => {
    const state = stateRef.current;
    const position = parsePersistedPosition({
      version: 1,
      x: state.nekoPosX,
      y: state.nekoPosY,
    });
    if (!position) return;
    try {
      window.localStorage.setItem(storageKey, JSON.stringify(position));
    } catch {
      // Position persistence is optional when browser storage is unavailable.
    }
  };
}

const OUTLINE = "#1b1b1b";

/**
 * Inline SVG for pixel art given as rows of characters ("." is transparent), outlined in the
 * sprite's dark ink so it reads on light and dark pages. The result is one pixel larger on each side.
 */
export function pixelArtSVG(rows: readonly string[], colors: Record<string, string>): string {
  const width = rows[0].length + 2;
  const height = rows.length + 2;
  const filled = (x: number, y: number) => Boolean(colors[rows[y]?.[x] ?? "."]);
  const rects: string[] = [];
  for (let y = -1; y <= rows.length; y++) {
    for (let x = -1; x <= rows[0].length; x++) {
      const fill = filled(x, y)
        ? colors[rows[y][x]]
        : filled(x - 1, y) || filled(x + 1, y) || filled(x, y - 1) || filled(x, y + 1)
          ? OUTLINE
          : null;
      if (fill) rects.push(`<rect x="${x + 1}" y="${y + 1}" width="1" height="1" fill="${fill}"/>`);
    }
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" shape-rendering="crispEdges" style="display:block;width:100%;height:100%">${rects.join("")}</svg>`;
}

