export interface StartCatAnimationOptions {
  stateRef: { current: CatRuntimeState };
  elRef: { current: HTMLDivElement | null };
  lastStateRef: { current: CatActivityState };
  onStateChangeRef: { current: ((state: CatActivityState) => void) | undefined };
  liveStateRef?: { current: CatLiveState };
  persistPosition: boolean;
  storageKey?: string;
  zIndex: number;
  /** Make the cat a keyboard-reachable "Pet the cat" button. */
  pettable?: boolean;
}

type EngineOptionKey = Exclude<
  keyof StartCatAnimationOptions,
  "stateRef" | "elRef" | "lastStateRef" | "onStateChangeRef" | "liveStateRef"
>;

/** Options fixed for one engine run. Each must be listed, so hosts restart the cat when one changes. */
const RESTART_OPTIONS = {
  persistPosition: true,
  storageKey: true,
  zIndex: true,
  pettable: true,
} satisfies Record<EngineOptionKey, true>;
export const ENGINE_OPTION_KEYS = Object.keys(RESTART_OPTIONS) as EngineOptionKey[];

/** The laser toy runs only while the cat is chasing. */
export function laserActive(options: {
  laserPointer: boolean;
  followCursor: boolean;
  paused: boolean;
}): boolean {
  return options.laserPointer && options.followCursor && !options.paused;
}

function createDebugWrapper(
  zIndex: number,
  debugHUD: HTMLDivElement,
  debugControls: HTMLDivElement,
) {
  const debugWrapper = document.createElement("div");
  debugWrapper.setAttribute("aria-hidden", "true");
  debugWrapper.style.cssText = [
    "position:fixed",
    "top:10px",
    "left:10px",
    `z-index:${zIndex}`,
    "display:none",
    "flex-direction:column",
    "gap:6px",
    "pointer-events:none",
  ].join(";");
  debugWrapper.appendChild(debugHUD);
  debugWrapper.appendChild(debugControls);
  return debugWrapper;
}

export function startCatAnimation({
  stateRef,
  elRef,
  lastStateRef,
  onStateChangeRef,
  liveStateRef,
  persistPosition,
  storageKey = ONEKO_DEFAULTS.storageKey,
  zIndex,
  pettable = ONEKO_DEFAULTS.pettable,
}: StartCatAnimationOptions): () => void {
  stateRef.current.bubbleVisible = false;
  stateRef.current.bubbleTimer = 0;
  stateRef.current.zIndex = zIndex;
  stateRef.current.affectionKey = `${storageKey}:affection`;
  const el = createCatElement(stateRef.current, zIndex);
  elRef.current = el;
  const debugSVG = createDebugSVG(zIndex);
  const debugHUD = createDebugHUD();
  const { wrapper: bubbleEl, textEl: bubbleTextEl, tailWrap: bubbleTail } = createBubble(zIndex);

  const deps = {
    stateRef,
    el,
    bubbleEl,
    bubbleTextEl,
    bubbleTail,
    debugSVG,
    debugHUD,
    lastStateRef,
    onStateChangeRef,
    liveStateRef,
  };

  const play = createPlay(deps);
  const frame = createFrameLoop(deps, play);
  const debugControls = createDebugControls({
    stateRef,
    el,
    bubbleEl,
    bubbleTextEl,
    frame,
    showBubble: () => showBubble(deps, { forced: true }),
    hideBubble: () => hideBubble(deps),
    bubbleDisplayFrames: BUBBLE_DISPLAY_FRAMES,
  });
  const debugWrapper = createDebugWrapper(zIndex, debugHUD, debugControls);

  if (persistPosition) {
    loadPersistedCatState(stateRef, el, storageKey);
  }

  refreshZones(deps);

  document.body.appendChild(debugSVG);
  document.body.appendChild(debugWrapper);
  document.body.appendChild(el);
  document.body.appendChild(bubbleEl);

  const onMouseMove = createMouseMoveHandler(deps);
  document.addEventListener("mousemove", onMouseMove);
  const onPointerDown = (event: PointerEvent) => {
    if (event.pointerType !== "touch") return;
    if (
      event.target instanceof Element &&
      event.target.closest(
        "button,a,input,select,textarea,label,summary,[role='button'],[data-oneko-cat]",
      )
    )
      return;
    onMouseMove(event);
  };
  document.addEventListener("pointerdown", onPointerDown);

  // Zones are re-read on the next tick; the page-wide obstacle scan waits until scrolling settles.
  let settle: ReturnType<typeof setTimeout> | undefined;
  const invalidateObstacles = () => {
    stateRef.current.zoneState.collectedFrame = -Infinity;
    clearTimeout(settle);
    settle = setTimeout(() => {
      stateRef.current.lastObstacleRefresh = -OBSTACLE_INTERVAL;
      stateRef.current.lastPathRecalcFrame = -PATH_RECALC_INTERVAL;
    }, SCROLL_SETTLE_MS);
  };
  window.addEventListener("scroll", invalidateObstacles, { passive: true });
  window.addEventListener("resize", invalidateObstacles, { passive: true });

  const persist = persistPosition ? createPersistHandler(stateRef, storageKey) : null;
  const onVisibilityChange = () => {
    if (document.hidden) persist?.();
  };
  if (persist) {
    document.addEventListener("visibilitychange", onVisibilityChange);
    window.addEventListener("pagehide", persist);
  }

  const onKeyDown = createKonamiHandler(stateRef, debugSVG, debugWrapper);
  document.addEventListener("keydown", onKeyDown);

  const leavePack = joinPack(stateRef.current);
  const stopWatchingPage = watchPage(deps);
  const stopPetting = pettable ? makePettable(deps) : undefined;
  const stopAnimationLoop = startAnimationLoop(stateRef, frame);

  return () => {
    stopPetting?.();
    stopWatchingPage();
    play.dispose();
    leavePack();
    if (packSize() === 0) {
      clearTreats();
      restoreKnocked();
    }
    persist?.();
    clearTimeout(settle);
    teardownCatAnimation(
      { el, debugSVG, debugWrapper, bubbleEl },
      {
        onMouseMove,
        onPointerDown,
        onKeyDown,
        invalidateObstacles,
        persist,
        onVisibilityChange,
        stopAnimationLoop,
      },
    );
    elRef.current = null;
    stateRef.current.bubbleVisible = false;
    stateRef.current.bubbleTimer = 0;
    if (liveStateRef) liveStateRef.current.bubbleVisible = false;
  };
}

type CatAnimationElements = {
  el: HTMLDivElement;
  debugSVG: SVGSVGElement;
  debugWrapper: HTMLDivElement;
  bubbleEl: HTMLDivElement;
};

type CatAnimationListeners = {
  onMouseMove: (ev: MouseEvent) => void;
  onPointerDown: (event: PointerEvent) => void;
  onKeyDown: (e: KeyboardEvent) => void;
  invalidateObstacles: () => void;
  persist: (() => void) | null;
  onVisibilityChange: () => void;
  stopAnimationLoop: () => void;
};

export function teardownCatAnimation(
  { el, debugSVG, debugWrapper, bubbleEl }: CatAnimationElements,
  {
    onMouseMove,
    onPointerDown,
    onKeyDown,
    invalidateObstacles,
    persist,
    onVisibilityChange,
    stopAnimationLoop,
  }: CatAnimationListeners,
) {
  document.removeEventListener("mousemove", onMouseMove);
  document.removeEventListener("pointerdown", onPointerDown);
  document.removeEventListener("keydown", onKeyDown);
  window.removeEventListener("scroll", invalidateObstacles);
  window.removeEventListener("resize", invalidateObstacles);
  if (persist) {
    document.removeEventListener("visibilitychange", onVisibilityChange);
    window.removeEventListener("pagehide", persist);
  }
  stopAnimationLoop();

  for (const node of [el, debugSVG, debugWrapper, bubbleEl]) {
    if (node.parentNode) {
      node.parentNode.removeChild(node);
    }
  }
}

import { pixelArtSVG } from "./pixel-art";

/** A treat on the page, shared by every cat: the first to reach it eats it. */
export interface Treat {
  x: number;
  y: number;
  el: HTMLDivElement;
  eaten: boolean;
}

const FISH = pixelArtSVG([".OO...O", "OOOO.OO", "OBOOOOO", "OOOO.OO", ".OO...O"], {
  O: "#f4a261",
  B: "#1b1b1b",
});
/** Each fish pixel is drawn this many CSS pixels wide. */
const PIXEL = 2;
const MAX_TREATS = 5;
const treats: Treat[] = [];

/** The uneaten treat closest to a point, or undefined when the floor is clean. */
export function nearestTreat(
  x: number,
  y: number,
  skip?: (treat: Treat) => boolean,
): Treat | undefined {
  let best: Treat | undefined;
  for (const treat of treats)
    if (skip?.(treat)) continue;
    else if (!best || Math.hypot(treat.x - x, treat.y - y) < Math.hypot(best.x - x, best.y - y))
      best = treat;
  return best;
}

/** Drop a treat at a viewport point. Older treats disappear past five on the floor. */
export function dropTreat(x: number, y: number, zIndex: number): Treat {
  const el = document.createElement("div");
  el.setAttribute("aria-hidden", "true");
  el.setAttribute("data-oneko-treat", "");
  el.innerHTML = FISH;
  const width = 9 * PIXEL;
  const height = 7 * PIXEL;
  const clampedX = Math.max(width, Math.min(window.innerWidth - width, x));
  const clampedY = Math.max(height, Math.min(window.innerHeight - height, y));
  el.style.cssText = [
    "position:fixed",
    "pointer-events:none",
    `left:${clampedX - width / 2}px`,
    `top:${clampedY - height / 2}px`,
    `width:${width}px`,
    `height:${height}px`,
    `z-index:${zIndex}`,
  ].join(";");
  document.body.appendChild(el);
  el.animate?.(
    [
      { transform: "translateY(-14px)", opacity: 0 },
      { transform: "none", opacity: 1 },
    ],
    { duration: 220, easing: "cubic-bezier(0.3, 1.4, 0.6, 1)" },
  );
  const treat = { x: clampedX, y: clampedY, el, eaten: false };
  treats.push(treat);
  while (treats.length > MAX_TREATS) removeTreat(treats[0]);
  return treat;
}

function removeTreat(treat: Treat) {
  treat.eaten = true;
  treat.el.remove();
  const index = treats.indexOf(treat);
  if (index !== -1) treats.splice(index, 1);
}

/** Eat a treat. Returns false when another cat got there first. */
export function eatTreat(treat: Treat): boolean {
  if (treat.eaten) return false;
  removeTreat(treat);
  return true;
}

export function clearTreats(): void {
  while (treats.length) removeTreat(treats[0]);
}

