  | "moving"
  | "sleeping"
  | "scratchSelf"
  | "tired"
  | "alert"
  | "scratchWallN"
  | "scratchWallS"
  | "scratchWallE"
  | "scratchWallW"
  | "freerun";

export type IdleActivityState = Exclude<CatActivityState, "idle" | "moving" | "freerun">;

/** A moment the cat can make a sound. Wall scratching in any direction shares one. */
export type OnekoSoundEvent =
  | Exclude<CatActivityState, `scratchWall${string}`>
  | "scratchWall"
  | "pet"
  | "eat"
  | "hiss";

/** Clip URLs by moment. An array is a pool to pick from; an empty array silences that moment. */
export type OnekoSounds = Partial<Record<OnekoSoundEvent, string | readonly string[]>>;

export interface CatLiveState {
  state: CatActivityState;
  posX: number;
  posY: number;
  velMag: number;
  idleTime: number;
  distToMouse: number;
  frameCount: number;
  freerunActive: boolean;
  freerunTimer: number;
  bubbleVisible: boolean;
  pathLength: number;
  obstacleCount: number;
}

export interface OnekoProps {
  /** Freeze animation in place without unmounting. Default false. */
  paused?: boolean;
  /** Chase the pointer and visit favorite spots. False keeps the cat resting in place. Default true. */
  followCursor?: boolean;
  /** Allow the cat to nap while idle. Default true. */
  sleepEnabled?: boolean;
  /** Preferred bubble side; auto chooses the side with room. Default auto. */
  bubblePlacement?: (typeof BUBBLE_PLACEMENTS)[number];
  /** Bubble size multiplier, in addition to scale (0.5–2). Default 1. */
  bubbleScale?: number;
  /** Directory URL for the optional .ogg sounds. Default /cat-sounds. */
  soundBasePath?: string;
  /** Your own clips for chosen moments, as full URLs. Other moments keep the built-in sounds. */
  sounds?: OnekoSounds;
  /** localStorage key for position persistence. Default oneko. */
  storageKey?: string;
  /** Strict keep-out areas and occasional favorite spots. DOM data-oneko-zone attributes also work. */
  zones?: readonly OnekoZone[];
  /** Chance to visit a favorite at each five-second check (0–1). Default 0.3. */
  zoneAttractionChance?: number;
  /** Time spent pursuing a favorite, in milliseconds. Default 4000. */
  zoneAttractionDuration?: number;
  /** Built-in pixel-art skin. Default classic. */
  skin?: OnekoSkin;
  /** Custom 256×128 sprite-sheet URL using the classic 8×4 layout. Overrides skin. */
  spriteSrc?: string;
  persistPosition?: boolean;
  zIndex?: number;
  initialPos?: { x: number; y: number };
  speed?: number;
  scale?: number;
  opacity?: number;
  rotationAmount?: number;
  idleThreshold?: number;
  /** Enable optional sound assets supplied by the host app. Default false. */
  meow?: boolean;
  onStateChange?: (state: CatActivityState) => void;
  /** Probability per frame cat enters freerun mode (0–1). Default 0.06 */
  freerunChance?: number;
  /** Duration of freerun in frames. Default 40 */
  freerunDuration?: number;
  /** Whether chat bubbles are enabled. Default true */
  bubbleEnabled?: boolean;
  /** How many frames a bubble stays visible. Default 180 */
  bubbleDisplayFrames?: number;
  /** Cooldown frames between bubbles. Default 120 */
  bubbleCooldown?: number;
  /** CSS hue-rotate degrees (0–360). Default 0 */
  hueRotate?: number;
  /** Mutable ref that oneko writes live state to every frame */
  liveStateRef?: { current: CatLiveState };
  /** Bubble trigger probability while idle (0–1). Default 0.5 */
  bubbleChance?: number;
  /** Distance in px at which cat stops chasing cursor. Default 20 */
  followDistance?: number;
  /** Multiplier for idle animation speed (0.5–2). Default 1 */
  animationSpeed?: number;
  /** Custom awake bubble text, or a pool of thoughts picked without immediate repeats. */
  bubbleText?: string | readonly string[];
  /** Sound volume (0–1). Default 0.5 */
  volume?: number;
  /** Show a red laser dot in place of the system cursor. Default false */
  laserPointer?: boolean;
  /** With reduced motion: "hide" the cat, or let it "rest" as a still, sleeping sprite. Default "hide" */
  reducedMotion?: (typeof REDUCED_MOTION_MODES)[number];
  /** What to chase: the cursor, or the cat mounted just before this one. Default "cursor" */
  chase?: (typeof CHASE_TARGETS)[number];
  /** Doze off while the visitor types in a field; wake on the next pointer move. Default false */
  napWhileTyping?: boolean;
  /** Walk over to whatever receives keyboard focus. Default false */
  followFocus?: boolean;
  /** Sit on a link or button after the pointer rests on it. Default false */
  perchOnHover?: boolean;
  /** Make the cat a keyboard-reachable "Pet the cat" button. Default false */
  pettable?: boolean;
  /** Wear a holiday hat around Halloween, the winter holidays, and New Year. A season name forces it. Default true */
  seasonal?: boolean | OnekoSeason;
  /** Let visitors pick the cat up and toss it; a click without dragging pets it. Default false */
  grabbable?: boolean;
  /** Double-click empty page space to drop a treat the cat runs over to eat. Default false */
  treats?: boolean;
  /** Follow the visitor's clock: zoomies at dawn and dusk, sleepy late at night. Default false */
  timeOfDay?: boolean;
  /** Remember pets and treats in localStorage and greet returning visitors. Default false */
  affection?: boolean;
  /** Called when the cat is petted by keyboard, click, or pet(). */
  onPet?: (detail: { affection: number }) => void;
  /** Called when the cat catches up with the cursor after a chase. */
  onCatchCursor?: () => void;
  /** Called when the cat falls asleep. */
  onSleep?: () => void;
  /** Called when a visitor throws the cat; speed is in CSS pixels per second. */
  onToss?: (detail: { speed: number }) => void;
  /** Called when the cat eats a treat. */
  onTreat?: (detail: { affection: number }) => void;
}

/** Event callbacks, kept in the runtime state so they update without a restart. */
export type OnekoEventHandlers = Pick<
  OnekoProps,
  "onPet" | "onCatchCursor" | "onSleep" | "onToss" | "onTreat"
>;

export interface ObstacleRect {
  left: number;
  top: number;
  right: number;
  bottom: number;
}

export interface PathPoint {
  x: number;
  y: number;
}

export interface CatRuntimeState {
  zoneState: ZoneRuntimeState;
  nekoPosX: number;
  nekoPosY: number;
  nekoVelX: number;
  nekoVelY: number;
  mousePosX: number;
  mousePosY: number;
  frameCount: number;
  idleTime: number;
  idleAnimation: IdleActivityState | null;
  idleAnimationFrame: number;
  obstacleRects: ObstacleRect[];
  lastObstacleRefresh: number;
  grid: Uint8Array | null;
  gridCols: number;
  gridRows: number;
  currentPath: PathPoint[];
  pathWaypointIdx: number;
  lastPathRecalcFrame: number;
  lastPathTargetCol: number;
  lastPathTargetRow: number;
  debugMode: boolean;
  paused: boolean;
  /** Options as resolved by applyRuntimeConfig; read this, never the props. */
  cfg: CatConfig;
  stateLocked: boolean;
  noFollow: boolean;
  currentRotation: number;
  soundCooldown: number;
  bubbleTimer: number;
  bubbleCooldown: number;
  bubbleVisible: boolean;
  lastBubbleMsg: number;
  loopPrevAngle: number | null;
  mouseCircleWinding: number;
  freerunMode: boolean;
  freerunTimer: number;
  lastFreerunMsg: number;
  laserCaught: boolean;
  /** Dozing because the visitor is typing; cleared by pointer movement. */
  typingNap: boolean;
  /** Holding still while keyboard focus is on the cat. */
  held: boolean;
  /** Top of the hovered element the cat walks to and sits on. */
  perchTarget: PathPoint | null;
  /** Spot beside the element with keyboard focus, when followFocus is on; cleared by pointer movement. */
  focusTarget: PathPoint | null;
  /** Position of the cat this one chases, when chase is "cat" and one exists. */
  leaderTarget: PathPoint | null;
  handlers: OnekoEventHandlers;
  /** Season currently worn, re-read from the calendar now and then. */
  season: OnekoSeason | null;
  /** Being carried, flying after a toss, or catching its breath after landing. */
  grab: GrabState | null;
  /** Something the cat set out to do: eat a treat, sit in a box, knock something over, or an API request. */
  errand: Errand | null;
  /** Frames until the cat looks for another box or knockable. */
  errandCooldown: number;
  /** Text queued by say() or data-oneko-say, shown on the next tick. */
  sayRequest: { text: string; frames: number } | null;
  /** The bubble was requested explicitly and stays up even when automatic bubbles are off. */
  bubbleForced: boolean;
  petRequest: boolean;
  /** Chasing a cursor that was far away; reaching it counts as a catch. */
  chasingFar: boolean;
  mood: Mood;
  moodCheckedFrame: number;
  affection: number;
  affectionLoaded: boolean;
  /** localStorage key for affection, derived from storageKey. */
  affectionKey: string;
  zIndex: number;
}

import { OBSTACLE_INTERVAL, PATH_RECALC_INTERVAL, TILE, ZONE_INTERVAL } from "./constants";
import {
  catZoneRadius,
  collectZones,
  containsPoint,
  expandRect,
  nearestSafePoint,
  type OnekoZone,
  type ResolvedZone,
} from "./zones";
import type { CatRuntimeState, ObstacleRect, PathPoint } from "./types";
import type { CatAnimationDeps } from "./animation/deps";
import { errandPoint } from "./animation/errand-point";

export const EMPTY_ZONES: readonly OnekoZone[] = [];
export type ZoneRuntimeState = {
  definitions: readonly OnekoZone[];
  blocked: ObstacleRect[];
  favorites: ResolvedZone[];
  signature: string;
  /** Frame the zone rects were last read from the DOM; -Infinity forces a re-read. */
  collectedFrame: number;
  targetId: string | null;
  visitFrames: number;
  cooldownFrames: number;
  chance: number;
  duration: number;
  movementTarget: PathPoint;
};

export function createZoneState(): ZoneRuntimeState {
  return {
    definitions: EMPTY_ZONES,
    blocked: [],
    favorites: [],
    signature: "",
    collectedFrame: -Infinity,
    targetId: null,
    visitFrames: 0,
    cooldownFrames: 50,
    chance: 0.3,
    duration: 40,
    movementTarget: { x: 0, y: 0 },
  };
}

/** Read zone rects from the DOM, and rebuild paths only when they moved. */
function collect(s: CatRuntimeState, radius: number) {
  const zones = s.zoneState;
  zones.collectedFrame = s.frameCount;
  const resolved = collectZones(zones.definitions);
  const signature = JSON.stringify([resolved, radius]);
  if (signature === zones.signature) return;
  zones.signature = signature;
  zones.blocked = resolved
    .filter((zone) => zone.type === "avoid")
    .map((zone) => expandRect(zone.rect, radius));
  zones.favorites = resolved.filter((zone) => zone.type === "attract");
  s.lastObstacleRefresh = -OBSTACLE_INTERVAL;
  s.lastPathRecalcFrame = -PATH_RECALC_INTERVAL;
}

export function refreshZones(deps: CatAnimationDeps): boolean {
  const s = deps.stateRef.current,
    zones = s.zoneState;
  const radius = catZoneRadius(s.cfg.scale);
  if (s.frameCount - zones.collectedFrame >= ZONE_INTERVAL) collect(s, radius);
  if (!zones.blocked.length) {
    deps.el.style.visibility = "";
    deps.bubbleEl.style.visibility = "";
    return true;
  }
  const safe = nearestSafePoint(
    { x: s.nekoPosX, y: s.nekoPosY },
    zones.blocked,
    window.innerWidth,
    window.innerHeight,
    radius,
  );
  deps.el.style.visibility = safe ? "" : "hidden";
  deps.bubbleEl.style.visibility = safe ? "" : "hidden";
  if (!safe) {
    s.nekoVelX = 0;
    s.nekoVelY = 0;
    return false;
  }
  if (safe.x !== s.nekoPosX || safe.y !== s.nekoPosY) {
    s.nekoPosX = safe.x;
    s.nekoPosY = safe.y;
    s.nekoVelX = 0;
    s.nekoVelY = 0;
    deps.el.style.left = `${safe.x - TILE / 2}px`;
    deps.el.style.top = `${safe.y - TILE / 2}px`;
    s.lastPathRecalcFrame = -PATH_RECALC_INTERVAL;
  }
  return true;
}

/** Favorites are sampled every five seconds, with a quiet gap after each visit. */
export function updateZoneTarget(
  s: CatRuntimeState,
  width: number,
  height: number,
  random = Math.random,
): void {
  const zones = s.zoneState;
  const oldId = zones.targetId;
  const radius = catZoneRadius(s.cfg.scale);
  const favorites = zones.favorites.filter((zone) => {
    const point = {
      x: (zone.rect.left + zone.rect.right) / 2,
      y: (zone.rect.top + zone.rect.bottom) / 2,
    };
    return (
      point.x >= radius &&
      point.x <= width - radius &&
      point.y >= radius &&
      point.y <= height - radius &&
      !zones.blocked.some((rect) => containsPoint(rect, point))
    );
  });
  // The laser toy and explicit debug controls keep priority over occasional visits.
  if (
    !s.cfg.followCursor ||
    s.cfg.laserPointer ||
    s.noFollow ||
    s.stateLocked ||
    zones.chance === 0
  ) {
    zones.targetId = null;
    zones.visitFrames = 0;
    zones.cooldownFrames = 50;
  } else if (zones.targetId) {
    zones.visitFrames--;
    if (zones.visitFrames <= 0 || !favorites.some((zone) => zone.id === zones.targetId)) {
      zones.targetId = null;
      zones.cooldownFrames = 80;
    }
  } else if (--zones.cooldownFrames <= 0) {
    zones.cooldownFrames = 50;
    if (favorites.length && random() < zones.chance) {
      const index = Math.min(favorites.length - 1, Math.floor(random() * favorites.length));
      zones.targetId = favorites[index].id;
      zones.visitFrames = zones.duration;
    }
  }
  const favorite = favorites.find((zone) => zone.id === zones.targetId);
  // Priority: an API request (goTo, sit), stay put, an errand (treat, box, knockable), a perch the
  // pointer rests on, a favorite spot, the lead cat, the focused element, the cursor.
  const errand = s.errand && errandPoint(s, s.errand);
  const requested = s.errand?.kind === "goTo" || s.errand?.kind === "sit";
  const desired =
    errand && requested
      ? errand
      : !s.cfg.followCursor || s.typingNap || s.held
        ? { x: s.nekoPosX, y: s.nekoPosY }
        : (errand ??
          s.perchTarget ??
          (favorite
            ? {
                x: (favorite.rect.left + favorite.rect.right) / 2,
                y: (favorite.rect.top + favorite.rect.bottom) / 2,
              }
            : (s.leaderTarget ?? s.focusTarget ?? { x: s.mousePosX, y: s.mousePosY })));
  zones.movementTarget = zones.blocked.length
    ? (nearestSafePoint(desired, zones.blocked, width, height, radius) ?? {
        x: s.nekoPosX,
        y: s.nekoPosY,
      })
    : desired;
  if (oldId !== zones.targetId) s.lastPathRecalcFrame = -PATH_RECALC_INTERVAL;
}

import { TILE } from "./constants";
import type { ObstacleRect, PathPoint } from "./types";

export type OnekoZone = {
  id: string;
  type: "avoid" | "attract";
  /** CSS selector. All matching visible elements become zones. */
  selector?: string;
  /** Fixed viewport coordinates in CSS pixels; selector takes precedence. */
  rect?: ObstacleRect;
  /** Extra space outside a keep-out zone, in pixels. */
  padding?: number;
};

export type ResolvedZone = { id: string; type: OnekoZone["type"]; rect: ObstacleRect };

function isValidRect(rect: ObstacleRect): boolean {
  return (
    Object.values(rect).every(Number.isFinite) && rect.right > rect.left && rect.bottom > rect.top
  );
}

export function expandRect(rect: ObstacleRect, padding: number): ObstacleRect {
  return {
    left: rect.left - padding,
    top: rect.top - padding,
    right: rect.right + padding,
    bottom: rect.bottom + padding,
  };
}

export function containsPoint(rect: ObstacleRect, point: PathPoint): boolean {
  return point.x > rect.left && point.x < rect.right && point.y > rect.top && point.y < rect.bottom;
}

/** Conservative radius also protects the corners when a scaled cat tilts. */
export function catZoneRadius(scale: number): number {
  return (TILE / 2) * Math.max(0.1, Number.isFinite(scale) ? scale : 1) * Math.SQRT2 + 1;
}

const elementIds = new WeakMap<Element, number>();
let nextElementId = 0;
function zoneElementId(element: Element): number {
  if (!elementIds.has(element)) elementIds.set(element, ++nextElementId);
  return elementIds.get(element)!;
}

export function collectZones(zones: readonly OnekoZone[]): ResolvedZone[] {
  const result: ResolvedZone[] = [];
  const add = (id: string, type: OnekoZone["type"], rect: ObstacleRect, padding = 0) => {
    if (!isValidRect(rect)) return;
    const extra = Number.isFinite(padding) ? Math.max(0, padding) : 0;
    result.push({ id, type, rect: expandRect(rect, type === "avoid" ? extra : 0) });
  };
  const addElement = (id: string, type: OnekoZone["type"], element: Element, padding = 0) => {
    const style = getComputedStyle(element);
    if (style.visibility === "hidden" || style.display === "none") return;
    const { left, top, right, bottom } = element.getBoundingClientRect();
    add(id, type, { left, top, right, bottom }, padding);
  };
  for (const zone of zones) {
    if (zone.type !== "avoid" && zone.type !== "attract") continue;
    if (zone.selector) {
      try {
        document
          .querySelectorAll(zone.selector)
          .forEach((element) =>
            addElement(`${zone.id}:${zoneElementId(element)}`, zone.type, element, zone.padding),
          );
      } catch {
        /* A stale or invalid selector must not stop the cat. */
      }
    } else if (zone.rect) add(zone.id, zone.type, zone.rect, zone.padding);
  }
  document
    .querySelectorAll('[data-oneko-zone="avoid"], [data-oneko-zone="attract"]')
    .forEach((element) => {
      addElement(
        `data-zone:${zoneElementId(element)}`,
        element.getAttribute("data-oneko-zone") as OnekoZone["type"],
        element,
      );
    });
  return result;
}

/** Find a safe center even when zones overlap or appear around a resting cat. */
export function nearestSafePoint(
  point: PathPoint,
  blocked: ObstacleRect[],
  width: number,
  height: number,
  margin: number,
): PathPoint | null {
  if (width < margin * 2 || height < margin * 2) return null;
  const clampX = (x: number) => Math.max(margin, Math.min(width - margin, x));
  const clampY = (y: number) => Math.max(margin, Math.min(height - margin, y));
  const origin = { x: clampX(point.x), y: clampY(point.y) };
  if (!blocked.some((rect) => containsPoint(rect, origin))) return origin;
  const xs = [
    origin.x,
    margin,
    width - margin,
    ...blocked.flatMap((rect) => [rect.left, rect.right]),
  ].map(clampX);
  const ys = [
    origin.y,
    margin,
    height - margin,
    ...blocked.flatMap((rect) => [rect.top, rect.bottom]),
  ].map(clampY);
  let closest: PathPoint | null = null;
  let distance = Infinity;
  for (const x of xs)
    for (const y of ys) {
      const candidate = { x, y };
      if (blocked.some((rect) => containsPoint(rect, candidate))) continue;
      const nextDistance = Math.hypot(x - point.x, y - point.y);
      if (nextDistance < distance) {
        distance = nextDistance;
        closest = candidate;
      }
    }
  return closest;
}

/** Swept collision: a fast cat cannot jump over a thin forbidden zone between ticks. */
export function constrainZoneMovement(
  from: PathPoint,
  to: PathPoint,
  blocked: ObstacleRect[],
): PathPoint {
  let limit = 1;
  const dx = to.x - from.x,
    dy = to.y - from.y;
  for (const rect of blocked) {
    let enter = -Infinity,
      leave = Infinity;
    let misses = false;
    for (const [position, delta, min, max] of [
      [from.x, dx, rect.left, rect.right],
      [from.y, dy, rect.top, rect.bottom],
    ]) {
      if (Math.abs(delta) < 1e-9) {
        if (position <= min || position >= max) {
          misses = true;
          break;
        }
      } else {
        const a = (min - position) / delta,
          b = (max - position) / delta;
        enter = Math.max(enter, Math.min(a, b));
        leave = Math.min(leave, Math.max(a, b));
      }
    }
    if (!misses && enter < leave && leave > 0 && enter >= 0 && enter < limit)
      limit = Math.max(0, enter - 0.001);
  }
  return { x: from.x + dx * limit, y: from.y + dy * limit };
}
